/* Re-theme with --mnv-tree-paper, -ink, -accent (and -warn for the legacy banner). */
.mnv-tree {
  --mnv-tree-paper: oklch(0.976 0.009 95);
  --mnv-tree-ink: oklch(0.27 0.03 150);
  --mnv-tree-accent: oklch(0.52 0.11 150);
  --mnv-tree-warn: oklch(0.66 0.13 70);

  --mnv-tree-line: color-mix(in oklch, var(--mnv-tree-ink) 11%, transparent);
  --mnv-tree-muted: color-mix(in oklch, var(--mnv-tree-ink) 66%, var(--mnv-tree-paper));
  --mnv-tree-faint: color-mix(in oklch, var(--mnv-tree-ink) 42%, var(--mnv-tree-paper));
  --mnv-tree-hover: color-mix(in oklch, var(--mnv-tree-ink) 5.5%, transparent);
  --mnv-tree-field: color-mix(in oklch, var(--mnv-tree-ink) 4.5%, var(--mnv-tree-paper));
  --mnv-tree-sel: color-mix(in oklch, var(--mnv-tree-accent) 14%, var(--mnv-tree-paper));
  --mnv-tree-ring: color-mix(in oklch, var(--mnv-tree-accent) 72%, transparent);
  --mnv-tree-ease: cubic-bezier(.2, .8, .2, 1);
  --mnv-tree-spring: linear(0, 0.06 3%, 0.24 7%, 0.6 14%, 0.86 21%, 1.01 29%, 1.06 35%, 1.05 42%, 1.01 55%, 0.995 70%, 1);
  --mnv-tree-step: 14px;

  position: relative;
  isolation: isolate;
  container-type: inline-size;
  color-scheme: light;
  box-sizing: border-box;
  width: 100%;
  height: 480px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  grid-template-areas: "head" "tools" "legacy" "tree" "foot";
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  color: var(--mnv-tree-ink);
  background: var(--mnv-tree-paper);
  box-shadow: 0 0 0 1px var(--mnv-tree-line), 0 24px 48px -30px oklch(0.3 0.06 150 / .5);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mnv-tree-accent);
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mnv-tree { --mnv-tree-spring: cubic-bezier(.3, 1.35, .5, 1); }
}
:where(.mnv-tree) *, :where(.mnv-tree) *::before, :where(.mnv-tree) *::after { box-sizing: border-box; }
:where(.mnv-tree) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnv-tree) :focus-visible { outline: 2px solid var(--mnv-tree-ring); outline-offset: 2px; }
.mnv-tree svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.mnv-tree__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- header ---------- */
.mnv-tree__head {
  grid-area: head;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 14px 14px 10px;
}
.mnv-tree__brand {
  display: inline-flex; align-items: center; gap: 7px; min-width: 0;
  & svg { width: 20px; height: 20px; color: var(--mnv-tree-accent); }
  & b { font-weight: 720; letter-spacing: -.015em; font-size: 14px; }
  & span { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--mnv-tree-faint); padding-top: 1px; }
}
.mnv-tree__ver {
  position: relative; display: inline-grid; align-items: center;
  & select {
    appearance: none; font: 600 11.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
    color: var(--mnv-tree-muted); background: var(--mnv-tree-field);
    border: 1px solid var(--mnv-tree-line); border-radius: 7px; padding: 6px 24px 6px 8px; cursor: pointer;
    transition: border-color .2s, color .2s;
  }
  & select:hover { color: var(--mnv-tree-ink); border-color: color-mix(in oklch, var(--mnv-tree-ink) 22%, transparent); }
  & select:focus-visible { outline: 2px solid var(--mnv-tree-ring); outline-offset: 1px; }
  & svg { position: absolute; right: 5px; width: 14px; height: 14px; pointer-events: none; color: var(--mnv-tree-faint); }
}

/* ---------- filter ---------- */
.mnv-tree__tools {
  grid-area: tools; position: relative;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; padding: 0 12px 10px;
  &::after {
    content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 10px; translate: 0 100%; z-index: 2;
    background: linear-gradient(var(--mnv-tree-line), transparent); opacity: 0; pointer-events: none; transition: opacity .25s;
  }
}
.mnv-tree__find {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 6px;
  height: 32px; padding: 0 6px 0 9px; border-radius: 8px;
  background: var(--mnv-tree-field); box-shadow: inset 0 0 0 1px var(--mnv-tree-line);
  color: var(--mnv-tree-faint); cursor: text;
  transition: box-shadow .2s var(--mnv-tree-ease), background-color .2s;
  &:has(input:focus-visible) { background: var(--mnv-tree-paper); box-shadow: inset 0 0 0 1.5px var(--mnv-tree-ring), 0 0 0 3px color-mix(in oklch, var(--mnv-tree-accent) 14%, transparent); }
  & input {
    min-width: 0; border: 0; background: none; outline: none; color: var(--mnv-tree-ink);
    font: inherit; font-size: 12.5px; padding: 0;
    &::placeholder { color: var(--mnv-tree-faint); }
    &::-webkit-search-cancel-button { display: none; }
  }
  &:has(input:not(:placeholder-shown)) kbd { opacity: 0; }
}
.mnv-tree kbd {
  display: grid; place-items: center; min-width: 18px; height: 18px; border-radius: 4px;
  font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--mnv-tree-faint);
  box-shadow: inset 0 0 0 1px var(--mnv-tree-line), inset 0 -1px 0 var(--mnv-tree-line);
  transition: opacity .15s;
}
.mnv-tree__fold {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--mnv-tree-muted);
  transition: background-color .2s, color .2s;
  &:hover { background: var(--mnv-tree-hover); color: var(--mnv-tree-ink); }
  &:active svg { scale: .86; }
  & svg { transition: scale .3s var(--mnv-tree-spring); }
}

/* ---------- legacy banner ---------- */
.mnv-tree__legacy {
  grid-area: legacy; margin: 0 12px 8px; padding: 7px 8px 7px 9px; border-radius: 8px;
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 7px;
  font-size: 11.5px; line-height: 1.35; text-wrap: pretty;
  color: color-mix(in oklch, var(--mnv-tree-warn) 50%, var(--mnv-tree-ink));
  background: color-mix(in oklch, var(--mnv-tree-warn) 14%, var(--mnv-tree-paper));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-tree-warn) 30%, transparent);
  &[hidden] { display: none; }
  & svg { width: 15px; height: 15px; color: var(--mnv-tree-warn); }
  & button { font-weight: 650; font-size: 11.5px; padding: 3px 7px; border-radius: 6px; white-space: nowrap; background: color-mix(in oklch, var(--mnv-tree-warn) 18%, transparent); }
  & button:hover { background: color-mix(in oklch, var(--mnv-tree-warn) 30%, transparent); }
  transition: opacity .3s, translate .35s var(--mnv-tree-ease);
  @starting-style { opacity: 0; translate: 0 -6px; }
}

/* ---------- tree ---------- */
.mnv-tree__scroll {
  grid-area: tree; position: relative; min-height: 0;
  overflow: auto; overscroll-behavior: contain; scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mnv-tree-ink) 18%, transparent) transparent;
  padding: 2px 8px 12px;
}
.mnv-tree__list, .mnv-tree [role="group"] { list-style: none; margin: 0; padding: 0; }
.mnv-tree__list { isolation: isolate; }
.mnv-tree [role="treeitem"] {
  outline: none;
  &:focus-visible > .mnv-tree__row { box-shadow: inset 0 0 0 2px var(--mnv-tree-ring); }
  &[hidden] { display: none; }
}
.mnv-tree__row {
  position: relative;
  display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; align-items: center; column-gap: 6px;
  min-height: 30px; margin-block: 1px;
  padding: 0 8px 0 calc(6px + (var(--lvl, 1) - 1) * var(--mnv-tree-step));
  border-radius: 7px; cursor: pointer; user-select: none;
  color: var(--mnv-tree-muted);
  transition: color .2s, background-color .2s, opacity .35s var(--mnv-tree-ease), translate .45s var(--mnv-tree-ease);
  transition-delay: 0s, 0s, calc(var(--i, 0) * 28ms), calc(var(--i, 0) * 28ms);
  @starting-style { opacity: 0; translate: -6px 0; }
  &:hover { color: var(--mnv-tree-ink); background: var(--mnv-tree-hover); }
  &::before {
    content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit;
    background: linear-gradient(var(--mnv-tree-accent), var(--mnv-tree-accent)) 0 50% / 3px 16px no-repeat, var(--mnv-tree-sel);
    opacity: 0; transition: opacity .2s;
  }
}
.mnv-tree__ico { display: none; }
.mnv-tree [aria-level="1"] > .mnv-tree__row {
  grid-template-columns: 16px auto minmax(0, 1fr) auto;
  color: var(--mnv-tree-ink); font-weight: 620;
  & .mnv-tree__ico { display: block; color: var(--mnv-tree-faint); transition: color .2s; }
}
.mnv-tree [aria-level="1"]:has([aria-selected="true"]) > .mnv-tree__row .mnv-tree__ico,
.mnv-tree [aria-level="1"][aria-selected="true"] > .mnv-tree__row .mnv-tree__ico { color: var(--mnv-tree-accent); }
.mnv-tree [aria-level="1"]:not(:first-child) { margin-top: 6px; }
.mnv-tree__label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnv-tree__label mark { color: inherit; background: color-mix(in oklch, var(--mnv-tree-accent) 24%, transparent); border-radius: 3px; padding: 0 1px; margin: 0 -1px; }
.mnv-tree__chev {
  display: grid; place-items: center; width: 16px; height: 16px; color: var(--mnv-tree-faint);
  & svg { width: 13px; height: 13px; stroke-width: 2.2; transition: rotate .45s var(--mnv-tree-spring); }
}
.mnv-tree [aria-expanded="true"] > .mnv-tree__row .mnv-tree__chev svg { rotate: 90deg; }
.mnv-tree [aria-busy="true"] > .mnv-tree__row .mnv-tree__chev {
  & svg { opacity: 0; }
  &::after {
    content: ""; position: absolute; width: 11px; height: 11px; border-radius: 50%;
    border: 1.75px solid color-mix(in oklch, var(--mnv-tree-accent) 25%, transparent); border-top-color: var(--mnv-tree-accent);
    animation: mnv-tree-spin .7s linear infinite;
  }
}
.mnv-tree__tag {
  font: 650 9.5px/1 system-ui, sans-serif; letter-spacing: .06em; text-transform: uppercase;
  padding: 3px 5px; border-radius: 5px; white-space: nowrap;
  color: var(--mnv-tree-accent); background: color-mix(in oklch, var(--mnv-tree-accent) 12%, transparent);
  &:empty { display: none; }
}
.mnv-tree [aria-selected="true"] > .mnv-tree__row {
  color: color-mix(in oklch, var(--mnv-tree-accent) 72%, var(--mnv-tree-ink)); font-weight: 600;
  &::before { opacity: 1; }
}
.mnv-tree [aria-disabled="true"] > .mnv-tree__row {
  cursor: not-allowed; color: var(--mnv-tree-faint);
  & .mnv-tree__label { text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--mnv-tree-ink) 22%, transparent); }
  & .mnv-tree__tag { color: var(--mnv-tree-faint); background: var(--mnv-tree-hover); }
  &:hover { background: transparent; }
}
.mnv-tree [aria-disabled="true"].is-nope > .mnv-tree__row { animation: mnv-tree-nope .38s var(--mnv-tree-ease); }

/* groups: 0fr -> 1fr, with an indent guide per level */
.mnv-tree__kids {
  display: grid; grid-template-rows: 0fr; visibility: hidden;
  transition: grid-template-rows .34s var(--mnv-tree-ease), visibility 0s .34s;
  & > [role="group"] { min-height: 0; overflow: hidden; position: relative; }
  & > [role="group"]::before {
    content: ""; position: absolute; top: 2px; bottom: 4px; width: 1px;
    left: calc(6px + (var(--lvl, 1) - 1) * var(--mnv-tree-step) + 7.5px);
    background: var(--mnv-tree-line); transition: background-color .3s;
  }
}
.mnv-tree [aria-expanded="true"] > .mnv-tree__kids { grid-template-rows: 1fr; visibility: visible; transition-delay: 0s; }
.mnv-tree__kids:has([aria-selected="true"]) > [role="group"]::before { background: color-mix(in oklch, var(--mnv-tree-accent) 55%, transparent); }
.mnv-tree__skel {
  height: 30px; margin: 1px 0; border-radius: 7px; position: relative;
  &::after {
    content: ""; position: absolute; top: 11px; height: 8px; border-radius: 4px;
    left: calc(28px + (var(--lvl, 1) - 1) * var(--mnv-tree-step)); width: calc(48% - var(--i) * 9%);
    background: linear-gradient(90deg, var(--mnv-tree-hover) 0 30%, color-mix(in oklch, var(--mnv-tree-ink) 12%, transparent) 50%, var(--mnv-tree-hover) 70%) 0 0 / 300% 100%;
    animation: mnv-tree-shimmer 1.1s linear infinite; animation-delay: calc(var(--i) * -120ms);
  }
}

/* ---------- empty ---------- */
.mnv-tree__empty {
  display: grid; justify-items: center; text-align: center; gap: 4px; padding: 30px 16px 10px;
  &[hidden] { display: none; }
  & svg { width: 44px; height: 44px; stroke-width: 1.6; color: var(--mnv-tree-faint); margin-bottom: 6px; }
  & p { margin: 0; }
  transition: opacity .3s, translate .4s var(--mnv-tree-ease);
  @starting-style { opacity: 0; translate: 0 6px; }
}
.mnv-tree__et { font-weight: 650; font-size: 13.5px; text-wrap: balance; & q { color: var(--mnv-tree-accent); } }
.mnv-tree__ed { color: var(--mnv-tree-muted); font-size: 12px; max-width: 30ch; text-wrap: pretty; }
.mnv-tree__clear {
  margin-top: 10px; padding: 7px 12px; border-radius: 8px; font-weight: 600; font-size: 12px;
  color: var(--mnv-tree-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-tree-accent) 40%, transparent);
  transition: background-color .2s;
  &:hover { background: color-mix(in oklch, var(--mnv-tree-accent) 9%, transparent); }
}

/* ---------- footer ---------- */
.mnv-tree__foot {
  grid-area: foot;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "path meta" "title title" "desc desc";
  gap: 2px 8px; padding: 10px 14px 12px; border-top: 1px solid var(--mnv-tree-line);
  background: color-mix(in oklch, var(--mnv-tree-ink) 2.5%, var(--mnv-tree-paper));
}
.mnv-tree__path { grid-area: path; font-size: 10.5px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--mnv-tree-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnv-tree__meta { grid-area: meta; font: 500 10.5px/1.4 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mnv-tree-faint); }
.mnv-tree__title { grid-area: title; font-size: clamp(14px, 4.2cqi, 16px); font-weight: 700; letter-spacing: -.015em; text-wrap: balance; }
.mnv-tree__desc { grid-area: desc; font-size: 12px; color: var(--mnv-tree-muted); text-wrap: pretty; }
.mnv-tree__foot.is-swap > * { animation: mnv-tree-swap .42s var(--mnv-tree-ease) both; animation-delay: calc(var(--i, 0) * 40ms); }

@container (max-width: 300px) {
  .mnv-tree__scroll { --mnv-tree-step: 11px; }
  .mnv-tree__head { padding-inline: 12px; }
  .mnv-tree__brand span { display: none; }
  .mnv-tree__desc { display: none; }
}
@container (min-width: 460px) {
  .mnv-tree__row { min-height: 32px; font-size: 13.5px; }
}

.mnv-tree[data-scrolled] .mnv-tree__tools::after { opacity: 1; }

@keyframes mnv-tree-spin { to { rotate: 360deg; } }
@keyframes mnv-tree-shimmer { to { background-position: -300% 0; } }
@keyframes mnv-tree-swap { from { opacity: 0; translate: 0 5px; filter: blur(2px); } }
@keyframes mnv-tree-nope { 20% { translate: -4px 0; } 45% { translate: 3px 0; } 70% { translate: -2px 0; } }

@media (prefers-reduced-motion: reduce) {
  .mnv-tree__row, .mnv-tree__kids, .mnv-tree__chev svg, .mnv-tree__legacy, .mnv-tree__empty { transition: none; }
  .mnv-tree__row { transition: color .2s, background-color .2s; }
  .mnv-tree__foot.is-swap > *, .mnv-tree [aria-disabled="true"].is-nope > .mnv-tree__row { animation: none; }
  .mnv-tree__skel::after { animation: none; }
  .mnv-tree [aria-busy="true"] > .mnv-tree__row .mnv-tree__chev::after { animation-duration: 2.4s; }
}

