const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const list = $('.mnv-tree__list'), input = $('.mnv-tree__find input'), scroller = $('.mnv-tree__scroll');
const empty = $('.mnv-tree__empty'), live = $('.mnv-tree__live'), ver = $('.mnv-tree__ver select');
const banner = $('.mnv-tree__legacy'), foot = $('.mnv-tree__foot');
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const norm = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const svg = (p) => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const ICON = {
  chev: '<path d="m9.5 6.5 5.5 5.5-5.5 5.5"/>',
  compass: '<circle cx="12" cy="12" r="8.5"/><path d="m15.2 8.8-1.9 4.5-4.5 1.9 1.9-4.5Z"/>',
  book: '<path d="M5 18.5V5.5a2 2 0 0 1 2-2h12v13H7a2 2 0 0 0-2 2Zm0 0a2 2 0 0 0 2 2h12"/>',
  code: '<path d="m8.5 7.5-5 4.5 5 4.5"/><path d="m15.5 7.5 5 4.5-5 4.5"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
};

const DATA = [
  { id: 'start', t: 'Getting started', icon: 'compass', kids: [
    { id: 'install', t: 'Install the CLI', d: 'Homebrew, apt, and a static binary for air-gapped hosts.', m: 3 },
    { id: 'first', t: 'Your first pipeline', d: 'Read a Postgres table, write Parquet, run it every hour.', m: 8 },
    { id: 'concepts', t: 'Concepts', kids: [
      { id: 'sources', t: 'Sources and sinks', d: 'Every connector, its delivery guarantee and its limits.', m: 6 },
      { id: 'checkpoints', t: 'Checkpoints', d: 'How progress is stored so a restart resumes instead of repeating.', m: 5 },
      { id: 'backfills', t: 'Backfills', d: 'Re-run a date range without writing any row twice.', m: 7, v4: true },
    ] },
  ] },
  { id: 'guides', t: 'Guides', icon: 'book', kids: [
    { id: 'migrate', t: 'Migrate from v3', d: 'The 11 config keys that moved, and a script that rewrites them.', m: 11, tag: 'New', v4: true },
    { id: 'schedule', t: 'Schedule runs', d: 'Cron, event triggers and run windows across time zones.', m: 6 },
    { id: 'secrets', t: 'Secrets and credentials', d: 'Reference vault paths instead of pasting keys into YAML.', m: 5 },
    { id: 'observe', t: 'Observability', kids: [
      { id: 'metrics', t: 'Metrics', d: 'The 14 metrics every pipeline exports, with units and labels.', m: 4 },
      { id: 'tracing', t: 'Tracing', d: 'Carry one trace from the source read to the sink commit.', m: 7, v4: true },
      { id: 'alerts', t: 'Alert rules', soon: true },
    ] },
  ] },
  { id: 'api', t: 'API reference', icon: 'code', kids: [
    { id: 'rest', t: 'REST', kids: [
      { id: 'pipelines', t: 'Pipelines', d: 'Create, pause and version pipelines. 9 endpoints.', m: 9 },
      { id: 'runs', t: 'Runs', d: 'List runs, stream logs, cancel a run in flight. 7 endpoints.', m: 6 },
      { id: 'webhooks', t: 'Webhooks', d: 'Signed run.finished and run.failed callbacks.', m: 4 },
    ] },
    { id: 'events', t: 'Event schema', lazy: [
      { id: 'evtypes', t: 'Event types', d: 'All 23 events, grouped by the object they describe.', m: 5 },
      { id: 'delivery', t: 'Delivery guarantees', d: 'At-least-once, ordered per pipeline, deduplicated by event id.', m: 4 },
      { id: 'retries', t: 'Retries', d: 'Backoff at 10 s, 1 min and 10 min, then hourly for a day.', m: 3 },
    ] },
  ] },
  { id: 'changelog', t: 'Changelog', icon: 'clock', d: 'What shipped in 4.2: incremental backfills and trace export.', m: 2, tag: '4.2' },
];

const recs = new Map();
const expanded = new Set(['guides', 'observe']);
let selected = 'tracing', snapshot = null, query = '';
const isParent = (n) => !!(n.kids || n.lazy);

function build(nodes, level, parent, ul) {
  nodes.forEach((n, i) => {
    const li = document.createElement('li');
    li.setAttribute('role', 'treeitem');
    li.setAttribute('aria-level', level);
    li.tabIndex = -1;
    li.dataset.id = n.id;
    li.style.setProperty('--lvl', level);
    li.style.setProperty('--i', i);
    const row = document.createElement('div');
    row.className = 'mnv-tree__row';
    row.innerHTML = '<span class="mnv-tree__chev">' + (isParent(n) ? svg(ICON.chev) : '') + '</span>' +
      '<span class="mnv-tree__ico">' + (n.icon ? svg(ICON[n.icon]) : '') + '</span>' +
