/* Re-theme with --mnv-tabs-chrome, -panel, -ink and -accent. */
.mnv-tabs {
  --mnv-tabs-chrome: oklch(0.17 0.006 255);
  --mnv-tabs-panel: oklch(0.215 0.007 255);
  --mnv-tabs-ink: oklch(0.93 0.008 255);
  --mnv-tabs-accent: oklch(0.74 0.14 32);

  --mnv-tabs-line: color-mix(in oklch, var(--mnv-tabs-ink) 9%, transparent);
  --mnv-tabs-muted: color-mix(in oklch, var(--mnv-tabs-ink) 62%, var(--mnv-tabs-panel));
  --mnv-tabs-faint: color-mix(in oklch, var(--mnv-tabs-ink) 38%, var(--mnv-tabs-panel));
  --mnv-tabs-hover: color-mix(in oklch, var(--mnv-tabs-ink) 6%, transparent);
  --mnv-tabs-pop: color-mix(in oklch, var(--mnv-tabs-ink) 5%, var(--mnv-tabs-panel));
  --mnv-tabs-ring: color-mix(in oklch, var(--mnv-tabs-accent) 80%, transparent);
  --mnv-tabs-ease: cubic-bezier(.22, 1, .36, 1);
  --mnv-tabs-r: 8px;

  position: relative;
  container-type: inline-size;
  color-scheme: dark;
  box-sizing: border-box;
  width: 100%;
  height: 340px;
  border-radius: 14px;
  background:
    repeating-linear-gradient(135deg, color-mix(in oklch, var(--mnv-tabs-ink) 5%, transparent) 0 1px, transparent 1px 7px),
    color-mix(in oklch, var(--mnv-tabs-chrome) 70%, black);
  color: var(--mnv-tabs-ink);
  font: 400 12.5px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
:where(.mnv-tabs) *, :where(.mnv-tabs) *::before, :where(.mnv-tabs) *::after { box-sizing: border-box; }
:where(.mnv-tabs) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnv-tabs) :focus-visible { outline: 2px solid var(--mnv-tabs-ring); outline-offset: -2px; }
.mnv-tabs svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.mnv-tabs__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.mnv-tabs kbd {
  display: inline-grid; place-items: center; min-width: 20px; height: 18px; padding: 0 4px; border-radius: 4px;
  font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--mnv-tabs-muted);
  box-shadow: inset 0 0 0 1px var(--mnv-tabs-line), inset 0 -1px 0 var(--mnv-tabs-line);
}

.mnv-tabs__win {
  position: relative;
  container: mnv-tabs-win / inline-size;
  width: 100%; min-width: 0; height: 100%;
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; grid-template-areas: "strip" "panel" "status";
  border-radius: 14px; overflow: hidden; overflow: clip;
  background: var(--mnv-tabs-chrome);
  box-shadow: 0 0 0 1px var(--mnv-tabs-line), 0 20px 40px -24px black;
}

/* ---------- strip ---------- */
.mnv-tabs__strip {
  grid-area: strip; position: relative;
  display: flex; align-items: flex-end; gap: 4px; padding: 7px 8px 0 9px;
  min-width: 0;
}
.mnv-tabs__list { position: relative; display: flex; align-items: flex-end; flex: 1 1 auto; min-width: 0; height: 33px; }
.mnv-tabs__tab {
  position: relative; flex: none;
  display: flex; align-items: center; gap: 6px;
  height: 33px; padding: 0 5px 0 9px; border-radius: var(--mnv-tabs-r) var(--mnv-tabs-r) 0 0;
  color: var(--mnv-tabs-faint); cursor: pointer; user-select: none; white-space: nowrap;
  &[hidden] { display: none; }
  &:hover { color: var(--mnv-tabs-muted); background-color: var(--mnv-tabs-hover); }
  &:focus-visible { outline-offset: -3px; }
  /* hairline separators between resting tabs, drawn as a background image so the pseudo-elements stay free */
  & + & { background-image: linear-gradient(var(--mnv-tabs-line), var(--mnv-tabs-line)); background-size: 1px 16px; background-position: 0 50%; background-repeat: no-repeat; }
  &[aria-selected="true"] + &, &:hover + &, &:hover { background-image: none; }
  &[aria-selected="true"] {
    color: var(--mnv-tabs-ink); background: var(--mnv-tabs-panel); background-image: none; z-index: 1;
    box-shadow: inset 0 2px 0 var(--mnv-tabs-accent);
    &::before, &::after {
      content: ""; position: absolute; bottom: 0; width: var(--mnv-tabs-r); height: var(--mnv-tabs-r);
      background: radial-gradient(circle at 0 0, transparent calc(var(--mnv-tabs-r) - .5px), var(--mnv-tabs-panel) var(--mnv-tabs-r));
      left: calc(var(--mnv-tabs-r) * -1);
    }
    &::after { left: auto; right: calc(var(--mnv-tabs-r) * -1); background: radial-gradient(circle at 100% 0, transparent calc(var(--mnv-tabs-r) - .5px), var(--mnv-tabs-panel) var(--mnv-tabs-r)); }
  }
  transition: opacity .25s, translate .3s var(--mnv-tabs-ease), color .18s, background-color .18s;
  @starting-style { opacity: 0; translate: 0 6px; }
}
.mnv-tabs__ft {
  display: grid; place-items: center; width: 18px; height: 14px; border-radius: 3.5px; flex: none;
  font: 700 7.5px/1 ui-monospace, Menlo, monospace; letter-spacing: -.02em;
  color: oklch(0.82 0.12 var(--h)); background: oklch(0.82 0.12 var(--h) / .14);
}
.mnv-tabs__name { font-size: 12px; max-width: 16ch; overflow: hidden; text-overflow: ellipsis; }
.mnv-tabs__x {
  position: relative; display: grid; place-items: center; width: 20px; height: 20px; border-radius: 5px;
  color: var(--mnv-tabs-faint); opacity: 0; transition: opacity .15s, background-color .15s, color .15s;
  & svg { width: 13px; height: 13px; stroke-width: 2; }
  &:hover { background: var(--mnv-tabs-hover); color: var(--mnv-tabs-ink); }
  &::after {
    content: ""; position: absolute; width: 7px; height: 7px; border-radius: 50%;
    background: var(--mnv-tabs-accent); scale: 0; transition: scale .25s var(--mnv-tabs-ease);
  }
}
.mnv-tabs__tab:is(:hover, [aria-selected="true"], :focus-visible) .mnv-tabs__x { opacity: 1; }
.mnv-tabs__tab[data-dirty] .mnv-tabs__x { opacity: 1; & svg { opacity: 0; } &::after { scale: 1; } }
.mnv-tabs__tab[data-dirty] .mnv-tabs__x:hover { & svg { opacity: 1; } &::after { scale: 0; } }
.mnv-tabs__ghost { position: absolute; pointer-events: none; z-index: 0; }

.mnv-tabs__more {
  flex: none; align-self: center; margin-bottom: 3px;
  display: inline-flex; align-items: center; gap: 1px; height: 26px; padding: 0 3px 0 7px; border-radius: 7px;
  color: var(--mnv-tabs-muted); box-shadow: inset 0 0 0 1px var(--mnv-tabs-line);
  transition: background-color .18s, color .18s, box-shadow .18s;
  &[hidden] { display: none; }
  &:hover, &[aria-expanded="true"] { color: var(--mnv-tabs-ink); background: var(--mnv-tabs-hover); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
  &:focus-visible { outline-offset: 2px; }
  & svg { width: 14px; height: 14px; transition: rotate .3s var(--mnv-tabs-ease); }
  &.has-dirty .mnv-tabs__count::after { content: ""; display: inline-block; width: 5px; height: 5px; margin-left: 4px; border-radius: 50%; background: var(--mnv-tabs-accent); vertical-align: 2px; }
}
.mnv-tabs__count { font: 650 11px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }

/* ---------- overflow menu ---------- */
.mnv-tabs__menu {
  position: absolute; top: 40px; right: 8px; z-index: 5;
  width: min(236px, calc(100% - 16px)); max-height: calc(100% - 76px); overflow: auto;
  display: grid; padding: 5px; border-radius: 11px;
  background: var(--mnv-tabs-pop);
  box-shadow: 0 0 0 1px var(--mnv-tabs-line), 0 14px 32px -8px oklch(0 0 0 / .6);
  transform-origin: calc(100% - 20px) 0;
  opacity: 1; scale: 1;
  transition: opacity .16s, scale .22s var(--mnv-tabs-ease), display .22s allow-discrete;
  @starting-style { opacity: 0; scale: .95; }
  &[hidden] { display: none; opacity: 0; scale: .97; }
}
.mnv-tabs__mi {
  display: grid; grid-template-columns: auto auto minmax(0, 1fr) 6px; align-items: center; column-gap: 8px;
  min-height: 30px; padding: 0 8px; border-radius: 7px; text-align: left; outline: none;
  color: var(--mnv-tabs-muted);
  & .mnv-tabs__mn { color: var(--mnv-tabs-ink); white-space: nowrap; }
  & small { font: 400 10.5px/1.3 ui-monospace, Menlo, monospace; color: var(--mnv-tabs-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: right; }
  & .mnv-tabs__dot { width: 6px; height: 6px; border-radius: 50%; background: var(--mnv-tabs-accent); }
  &:is(:hover, :focus) { background: color-mix(in oklch, var(--mnv-tabs-accent) 16%, transparent); }
  &:focus-visible { outline: none; box-shadow: inset 0 0 0 1px var(--mnv-tabs-ring); }
  &.is-cmd { grid-template-columns: 18px minmax(0, 1fr); color: var(--mnv-tabs-muted); & svg { width: 15px; height: 15px; justify-self: center; } }
  &[aria-disabled="true"] { opacity: .45; cursor: default; }
  transition: opacity .2s, translate .25s var(--mnv-tabs-ease);
  transition-delay: calc(var(--i, 0) * 22ms);
  @starting-style { opacity: 0; translate: 0 -3px; }
}
.mnv-tabs__sep { height: 1px; margin: 4px 6px; background: var(--mnv-tabs-line); }

/* ---------- panel ---------- */
.mnv-tabs__panel {
  grid-area: panel; position: relative; min-height: 0;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  background: var(--mnv-tabs-panel); outline: none;
  &:focus-visible { box-shadow: inset 0 0 0 1px var(--mnv-tabs-ring); }
}
.mnv-tabs__crumbs {
  display: flex; align-items: center; gap: 4px; padding: 7px 14px 2px; min-width: 0;
  font-size: 11.5px; color: var(--mnv-tabs-faint); white-space: nowrap; overflow: hidden;
  & b { color: var(--mnv-tabs-muted); font-weight: 550; }
  & svg { width: 11px; height: 11px; stroke-width: 2; }
}
.mnv-tabs__code {
  margin: 0; padding: 6px 0 14px; overflow: auto; min-height: 0;
