      (f.dirty ? '<span class="mnv-tabs__dot"></span><span class="mnv-tabs__sr">, unsaved</span>' : '<span></span>') + '</button>';
  }).join('') +
    '<div class="mnv-tabs__sep" role="separator"></div>' +
    '<button type="button" role="menuitem" tabindex="-1" class="mnv-tabs__mi is-cmd" data-cmd="close-saved" style="--i:' + overflow.length + '"' + (saved ? '' : ' aria-disabled="true"') + '>' +
    '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 7h15M9.5 7V4.5h5V7M6.5 7l1 12.5h9l1-12.5"/></svg><span>Close saved editors (' + saved + ')</span></button>';
