menu.addEventListener('keydown', (e) => {
  const all = items(), k = all.indexOf(document.activeElement);
  if (e.key === 'ArrowDown') all[(k + 1) % all.length].focus();
  else if (e.key === 'ArrowUp') all[(k - 1 + all.length) % all.length].focus();
  else if (e.key === 'Home') all[0].focus();
  else if (e.key === 'End') all[all.length - 1].focus();
