@property --mnv-stepper-p {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

/* Re-theme with --mnv-stepper-paper, -ink, -accent and -danger. */
.mnv-stepper {
  --mnv-stepper-paper: oklch(0.972 0.006 80);
  --mnv-stepper-ink: oklch(0.25 0.022 220);
  --mnv-stepper-accent: oklch(0.52 0.1 192);
  --mnv-stepper-danger: oklch(0.57 0.19 28);

  --mnv-stepper-card: color-mix(in oklch, white 70%, var(--mnv-stepper-paper));
  --mnv-stepper-line: color-mix(in oklch, var(--mnv-stepper-ink) 12%, transparent);
  --mnv-stepper-muted: color-mix(in oklch, var(--mnv-stepper-ink) 64%, var(--mnv-stepper-paper));
  --mnv-stepper-faint: color-mix(in oklch, var(--mnv-stepper-ink) 40%, var(--mnv-stepper-paper));
  --mnv-stepper-tint: color-mix(in oklch, var(--mnv-stepper-accent) 10%, var(--mnv-stepper-card));
  --mnv-stepper-ring: color-mix(in oklch, var(--mnv-stepper-accent) 70%, transparent);
  --mnv-stepper-ease: cubic-bezier(.2, .8, .2, 1);
  --mnv-stepper-spring: linear(0, 0.08 4%, 0.32 9%, 0.72 17%, 0.95 24%, 1.04 30%, 1.05 36%, 1.02 46%, 0.995 60%, 1);
  --mnv-stepper-p: 0;

  position: relative;
  container-type: inline-size;
  color-scheme: light;
  box-sizing: border-box;
  width: 100%;
  height: 520px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  grid-template-areas: "head" "nav" "now" "stage" "foot";
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  color: var(--mnv-stepper-ink);
  background: var(--mnv-stepper-paper);
  box-shadow: 0 0 0 1px var(--mnv-stepper-line), 0 26px 50px -34px oklch(0.3 0.05 220 / .55);
  font: 400 13px/1.42 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mnv-stepper-accent);
  transition: --mnv-stepper-p .7s var(--mnv-stepper-spring);
}
@supports not (transition-timing-function: linear(0, 1)) {
  .mnv-stepper { --mnv-stepper-spring: cubic-bezier(.3, 1.3, .5, 1); }
}
:where(.mnv-stepper) *, :where(.mnv-stepper) *::before, :where(.mnv-stepper) *::after { box-sizing: border-box; }
:where(.mnv-stepper) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnv-stepper) :focus-visible { outline: 2px solid var(--mnv-stepper-ring); outline-offset: 2px; }
:where(.mnv-stepper) fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }
.mnv-stepper svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.mnv-stepper__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- header ---------- */
.mnv-stepper__head {
  grid-area: head; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; padding: 16px 18px 4px;
  & p, & h3 { margin: 0; }
}
.mnv-stepper__eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--mnv-stepper-accent); }
.mnv-stepper__h { font-size: clamp(16px, 5cqi, 19px); font-weight: 720; letter-spacing: -.02em; text-wrap: balance; }
.mnv-stepper__count {
  font-variant-numeric: tabular-nums; color: var(--mnv-stepper-faint); font-size: 12px; white-space: nowrap;
  & b { font-size: 22px; font-weight: 700; letter-spacing: -.03em; color: var(--mnv-stepper-ink); margin-right: 2px; }
}

/* ---------- the stepper ---------- */
.mnv-stepper__nav { grid-area: nav; position: relative; padding: 14px 10px 6px; }
.mnv-stepper__steps {
  list-style: none; margin: 0; padding: 0; position: relative;
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
}
.mnv-stepper__track {
  position: absolute; top: calc(14px + 14px - 1.5px); left: calc(10px + 12.5% - 2.5px); right: calc(10px + 12.5% - 2.5px); height: 3px;
  border-radius: 2px; background: var(--mnv-stepper-line);
  & i {
    position: absolute; inset: 0; border-radius: inherit; transform-origin: 0 50%;
    background: var(--mnv-stepper-accent);
    transform: scaleX(var(--mnv-stepper-p));
  }
}
.mnv-stepper__step {
  width: 100%; display: grid; justify-items: center; gap: 6px; padding: 0 2px 4px; border-radius: 10px;
  text-align: center;
  &:focus-visible { outline-offset: 0; }
}
.mnv-stepper__mark {
  position: relative; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%;
  font: 650 12px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums;
  color: var(--mnv-stepper-muted); background: var(--mnv-stepper-paper);
  box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--mnv-stepper-ink) 22%, transparent);
  transition: background-color .3s, color .3s, box-shadow .3s, scale .4s var(--mnv-stepper-spring);
  & > * { grid-area: 1 / 1; }
  & svg { width: 16px; height: 16px; stroke-width: 2.4; opacity: 0; }
  & .mnv-stepper__ok path { stroke-dasharray: 18; stroke-dashoffset: 18; transition: stroke-dashoffset .38s .12s var(--mnv-stepper-ease); }
  &::after {
    content: ""; position: absolute; inset: -5px; border-radius: 50%;
    box-shadow: 0 0 0 2px var(--mnv-stepper-accent); opacity: 0; pointer-events: none;
  }
}
.mnv-stepper__step:hover .mnv-stepper__mark { scale: 1.08; }
.mnv-stepper__txt {
  display: grid; gap: 1px; min-width: 0; max-width: 100%;
  & b { font-size: 12.5px; font-weight: 600; color: var(--mnv-stepper-muted); transition: color .3s; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { font-size: 10.5px; color: var(--mnv-stepper-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: color .3s; }
}
.mnv-stepper__item[data-state="done"] {
  & .mnv-stepper__mark { color: white; background: var(--mnv-stepper-accent); box-shadow: none; }
  & .mnv-stepper__num { opacity: 0; }
  & .mnv-stepper__ok { opacity: 1; & path { stroke-dashoffset: 0; } }
  & .mnv-stepper__txt b { color: var(--mnv-stepper-ink); }
}
.mnv-stepper__item[data-state="current"] {
  & .mnv-stepper__mark { color: var(--mnv-stepper-accent); background: var(--mnv-stepper-card); box-shadow: inset 0 0 0 2px var(--mnv-stepper-accent), 0 0 0 4px color-mix(in oklch, var(--mnv-stepper-accent) 16%, transparent); }
  & .mnv-stepper__mark::after { animation: mnv-stepper-pulse .9s var(--mnv-stepper-ease) .15s; }
  & .mnv-stepper__txt b { color: var(--mnv-stepper-ink); font-weight: 700; }
  & .mnv-stepper__txt small { color: var(--mnv-stepper-accent); }
}
.mnv-stepper__item[data-state="error"] {
  & .mnv-stepper__mark { color: white; background: var(--mnv-stepper-danger); box-shadow: 0 0 0 4px color-mix(in oklch, var(--mnv-stepper-danger) 18%, transparent); animation: mnv-stepper-shake .42s var(--mnv-stepper-ease); }
  & .mnv-stepper__num { opacity: 0; }
  & .mnv-stepper__bang { opacity: 1; }
  & .mnv-stepper__txt b { color: var(--mnv-stepper-ink); font-weight: 700; }
  & .mnv-stepper__txt small { color: var(--mnv-stepper-danger); font-weight: 600; }
}
.mnv-stepper__item[data-state="locked"] {
  & .mnv-stepper__step { cursor: not-allowed; }
  & .mnv-stepper__mark { color: var(--mnv-stepper-faint); box-shadow: inset 0 0 0 1.5px var(--mnv-stepper-line); background: var(--mnv-stepper-paper); }
  & .mnv-stepper__step:hover .mnv-stepper__mark { scale: 1; }
  & .mnv-stepper__txt b { color: var(--mnv-stepper-faint); }
}
.mnv-stepper__item.is-nope .mnv-stepper__mark { animation: mnv-stepper-nope .42s var(--mnv-stepper-ease); }
.mnv-stepper__now {
  grid-area: now; display: none; margin: 0; padding: 0 18px 4px; text-align: center;
  font-size: 12px; color: var(--mnv-stepper-muted);
  & b { color: var(--mnv-stepper-ink); }
}

/* ---------- panels ---------- */
.mnv-stepper__stage {
  grid-area: stage; display: grid; min-height: 0; overflow: auto; overscroll-behavior: contain;
  margin: 8px 12px 0; padding: 4px 6px 14px; scrollbar-width: thin;
  border-top: 1px solid var(--mnv-stepper-line);
  & > section { grid-area: 1 / 1; min-width: 0; align-self: start; }
  & > section[hidden] { display: none; }
}
.mnv-stepper__ph { margin: 12px 0 10px; font-size: 14.5px; font-weight: 680; letter-spacing: -.01em; text-wrap: balance; outline: none; }
.mnv-stepper__hint { margin: -6px 0 10px; font-size: 12px; color: var(--mnv-stepper-muted); text-wrap: pretty; }
.mnv-stepper__cards { display: grid; gap: 8px; margin-bottom: 12px; }
.mnv-stepper__card {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 11px; cursor: pointer;
  background: var(--mnv-stepper-card); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line);
  transition: box-shadow .2s, background-color .2s;
  & input { margin: 0; width: 16px; height: 16px; }
  & span { display: grid; gap: 1px; min-width: 0; }
  & b { font-weight: 650; font-size: 13px; }
  & small { font-size: 11.5px; color: var(--mnv-stepper-muted); text-wrap: pretty; }
  & em { font-style: normal; font: 600 12px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: var(--mnv-stepper-muted); white-space: nowrap; }
  &:hover { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-stepper-ink) 26%, transparent); }
  &:has(input:checked) { background: var(--mnv-stepper-tint); box-shadow: inset 0 0 0 1.5px var(--mnv-stepper-accent); & em { color: var(--mnv-stepper-accent); } }
  &:has(input:focus-visible) { outline: 2px solid var(--mnv-stepper-ring); outline-offset: 2px; }
  & input:focus-visible { outline: none; }
}
.mnv-stepper__days {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; margin-bottom: 12px;
  & legend { font-size: 11.5px; font-weight: 600; color: var(--mnv-stepper-muted); margin-bottom: 6px; padding: 0; }
  & label { position: relative; display: block; cursor: pointer; }
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: inherit; }
  & span {
    display: grid; justify-items: center; gap: 1px; padding: 7px 4px 6px; border-radius: 10px;
    font-size: 10.5px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--mnv-stepper-muted);
    background: var(--mnv-stepper-card); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line);
    transition: background-color .2s, color .2s, box-shadow .2s, scale .3s var(--mnv-stepper-spring);
  }
  & b { font-size: 17px; font-weight: 700; letter-spacing: -.02em; color: var(--mnv-stepper-ink); font-variant-numeric: tabular-nums; text-transform: none; }
  & i { font-style: normal; font-size: 9px; letter-spacing: .08em; color: var(--mnv-stepper-danger); }
  & label:hover span { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-stepper-ink) 26%, transparent); }
  & input:checked + span { color: white; background: var(--mnv-stepper-accent); box-shadow: none; & b { color: white; } }
  & input:focus-visible + span { outline: 2px solid var(--mnv-stepper-ring); outline-offset: 2px; }
  & input:active + span { scale: .95; }
  & input:disabled + span { opacity: .55; cursor: not-allowed; background: transparent; & b { color: var(--mnv-stepper-faint); text-decoration: line-through; } }
  & label:has(input:disabled) { cursor: not-allowed; }
}
.mnv-stepper__field {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px;
  font-size: 12px; font-weight: 600; color: var(--mnv-stepper-muted);
  & select {
    font: 600 12.5px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: var(--mnv-stepper-ink);
    padding: 8px 10px; border-radius: 9px; border: 0; background: var(--mnv-stepper-card); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line);
  }
}

.mnv-stepper__parcels { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.mnv-stepper__parcel {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto auto; grid-template-areas: "name kg band rm" "err err err err";
  align-items: center; column-gap: 10px; padding: 7px 6px 7px 12px; border-radius: 11px;
  background: var(--mnv-stepper-card); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line);
  transition: box-shadow .2s, background-color .2s;
  &.is-new { transition: box-shadow .2s, background-color .2s, opacity .3s, translate .45s var(--mnv-stepper-ease); @starting-style { opacity: 0; translate: 0 -8px; } }
  &:has([aria-invalid="true"]) { box-shadow: inset 0 0 0 1.5px var(--mnv-stepper-danger); background: color-mix(in oklch, var(--mnv-stepper-danger) 5%, var(--mnv-stepper-card)); }
}
.mnv-stepper__pn { grid-area: name; font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mnv-stepper__kg {
  grid-area: kg; display: inline-flex; align-items: center; gap: 4px; padding: 0 8px 0 2px; height: 30px; border-radius: 8px;
  background: var(--mnv-stepper-paper); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line);
  font-size: 11.5px; color: var(--mnv-stepper-faint);
  & input {
    width: 5ch; border: 0; background: none; outline: none; padding: 0 0 0 6px; text-align: right;
    font: 600 13px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: var(--mnv-stepper-ink);
    -moz-appearance: textfield;
    &::-webkit-inner-spin-button, &::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
  }
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 1.5px var(--mnv-stepper-ring), 0 0 0 3px color-mix(in oklch, var(--mnv-stepper-accent) 14%, transparent); }
  &:has([aria-invalid="true"]) { box-shadow: inset 0 0 0 1.5px var(--mnv-stepper-danger); }
}
.mnv-stepper__band { grid-area: band; min-width: 6ch; text-align: right; font: 600 12.5px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: var(--mnv-stepper-muted); }
.mnv-stepper__rm {
  grid-area: rm; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 7px; color: var(--mnv-stepper-faint);
  transition: background-color .2s, color .2s;
  &:hover { background: color-mix(in oklch, var(--mnv-stepper-danger) 10%, transparent); color: var(--mnv-stepper-danger); }
  &:disabled { opacity: .35; cursor: not-allowed; background: none; color: var(--mnv-stepper-faint); }
  & svg { width: 14px; height: 14px; }
}
.mnv-stepper__err {
  grid-area: err; margin: 6px 0 1px; font-size: 11.5px; font-weight: 550; color: var(--mnv-stepper-danger);
  display: flex; gap: 5px; align-items: center; text-wrap: pretty;
  &[hidden] { display: none; }
  & svg { width: 13px; height: 13px; }
}
.mnv-stepper__prow { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 10px; }
.mnv-stepper__add {
  display: inline-flex; align-items: center; gap: 5px; padding: 7px 11px 7px 8px; border-radius: 9px;
  font-weight: 600; font-size: 12px; color: var(--mnv-stepper-accent);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-stepper-accent) 40%, transparent);
  transition: background-color .2s;
  &:hover { background: color-mix(in oklch, var(--mnv-stepper-accent) 8%, transparent); }
  &:disabled { color: var(--mnv-stepper-faint); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line); cursor: not-allowed; background: none; }
  & svg { width: 14px; height: 14px; stroke-width: 2.2; }
}
.mnv-stepper__weight { font-size: 11.5px; color: var(--mnv-stepper-muted); font-variant-numeric: tabular-nums; text-align: right; }

.mnv-stepper__check {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: 11px; cursor: pointer; font-size: 12.5px; font-weight: 550;
  box-shadow: inset 0 0 0 1px var(--mnv-stepper-line); transition: background-color .2s, box-shadow .2s;
  & input { margin: 0; width: 16px; height: 16px; }
  & em { font-style: normal; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--mnv-stepper-muted); }
  &:has(input:checked) { background: var(--mnv-stepper-tint); box-shadow: inset 0 0 0 1.5px var(--mnv-stepper-accent); & em { color: var(--mnv-stepper-accent); } }
}

.mnv-stepper__sum {
  margin: 0 0 12px; display: grid; border-radius: 12px; background: var(--mnv-stepper-card); box-shadow: inset 0 0 0 1px var(--mnv-stepper-line);
  & > div { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: 10px; row-gap: 1px; align-items: center; padding: 8px 8px 9px 12px; }
  & > div + div { border-top: 1px solid var(--mnv-stepper-line); }
  & dt { grid-column: 1; font-size: 10px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--mnv-stepper-faint); }
  & dd { grid-column: 1; margin: 0; font-size: 12.5px; font-weight: 600; min-width: 0; text-wrap: pretty; }
  & button { grid-column: 2; grid-row: 1 / span 2; }
  & dd small { display: block; font-weight: 400; font-size: 11.5px; color: var(--mnv-stepper-muted); }
  & button { font-size: 12px; font-weight: 600; color: var(--mnv-stepper-accent); padding: 2px 6px; border-radius: 6px; }
  & button:hover { background: color-mix(in oklch, var(--mnv-stepper-accent) 9%, transparent); }
}
.mnv-stepper__bill {
  width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums;
  & td { padding: 4px 2px; color: var(--mnv-stepper-muted); }
  & td:last-child { text-align: right; color: var(--mnv-stepper-ink); font-weight: 550; }
  & tr.is-total td { padding-top: 9px; border-top: 1px dashed color-mix(in oklch, var(--mnv-stepper-ink) 22%, transparent); font-weight: 700; color: var(--mnv-stepper-ink); font-size: 13.5px; }
}

.mnv-stepper__done {
  display: grid; justify-items: center; text-align: center; padding: 22px 8px 8px;
  & p { margin: 0 0 16px; max-width: 34ch; color: var(--mnv-stepper-muted); font-size: 12.5px; text-wrap: pretty; }
  & p b { color: var(--mnv-stepper-ink); font-variant-numeric: tabular-nums; }
  & .mnv-stepper__ph { margin: 12px 0 6px; font-size: 17px; }
}
.mnv-stepper__tick {
  width: 58px !important; height: 58px !important; color: var(--mnv-stepper-accent); stroke-width: 2.6 !important;
  & circle { stroke-dasharray: 145; stroke-dashoffset: 145; animation: mnv-stepper-draw .7s var(--mnv-stepper-ease) forwards; }
  & path { stroke-dasharray: 36; stroke-dashoffset: 36; animation: mnv-stepper-draw .4s .55s var(--mnv-stepper-ease) forwards; }
}
.mnv-stepper__again {
  padding: 9px 14px; border-radius: 10px; font-weight: 650; font-size: 12.5px; color: var(--mnv-stepper-accent);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-stepper-accent) 40%, transparent);
  &:hover { background: color-mix(in oklch, var(--mnv-stepper-accent) 8%, transparent); }
}

/* ---------- footer ---------- */
.mnv-stepper__foot {
  grid-area: foot; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 12px 14px 14px; border-top: 1px solid var(--mnv-stepper-line);
  background: color-mix(in oklch, white 45%, var(--mnv-stepper-paper));
  &[hidden] { display: none; }
}
.mnv-stepper__back, .mnv-stepper__next {
  display: inline-flex; align-items: center; gap: 4px; height: 38px; border-radius: 11px; font-weight: 650; font-size: 13px; white-space: nowrap;
  transition: background-color .2s, color .2s, opacity .2s, scale .3s var(--mnv-stepper-spring), filter .2s;
  &:active:not(:disabled) { scale: .97; }
}
.mnv-stepper__back {
  padding: 0 12px 0 6px; color: var(--mnv-stepper-muted);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--mnv-stepper-ink) 6%, transparent); color: var(--mnv-stepper-ink); }
  &:disabled { opacity: .35; cursor: not-allowed; }
}
.mnv-stepper__next {
  position: relative; padding: 0 10px 0 16px; color: white; background: var(--mnv-stepper-ink);
  box-shadow: 0 6px 14px -8px var(--mnv-stepper-ink);
  &:hover:not(:disabled) { filter: brightness(1.25); }
  &.is-book { background: var(--mnv-stepper-accent); box-shadow: 0 8px 18px -10px var(--mnv-stepper-accent); }
  &[aria-busy="true"] { cursor: progress; & svg { opacity: 0; } &::after {
    content: ""; position: absolute; right: 12px; width: 13px; height: 13px; border-radius: 50%;
    border: 2px solid color-mix(in oklch, white 35%, transparent); border-top-color: white; animation: mnv-stepper-spin .7s linear infinite;
  } }
}
.mnv-stepper__total {
  display: grid; justify-items: end; line-height: 1.15; min-width: 0;
  & small { font-size: 10.5px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--mnv-stepper-faint); }
  & b { font-size: 16px; font-weight: 720; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  &.is-bump b { animation: mnv-stepper-bump .4s var(--mnv-stepper-ease); }
}

@container (max-width: 330px) {
  .mnv-stepper__txt small { display: none; }
  .mnv-stepper__head { padding-inline: 14px; }
}
@container (max-width: 290px) {
  .mnv-stepper__txt { display: none; }
  .mnv-stepper__now { display: block; }
  .mnv-stepper__total small { display: none; }
}
@container (min-width: 460px) {
  .mnv-stepper__cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@keyframes mnv-stepper-pulse { from { opacity: .8; scale: .8; } to { opacity: 0; scale: 1.35; } }
@keyframes mnv-stepper-shake { 20% { translate: -4px 0; } 40% { translate: 4px 0; } 60% { translate: -2px 0; } 80% { translate: 2px 0; } }
@keyframes mnv-stepper-nope { 20% { translate: -4px 0; } 40% { translate: 4px 0; } 60% { translate: -2px 0; } 80% { translate: 2px 0; } }
@keyframes mnv-stepper-draw { to { stroke-dashoffset: 0; } }
@keyframes mnv-stepper-spin { to { rotate: 360deg; } }
@keyframes mnv-stepper-bump { 40% { translate: 0 -3px; color: var(--mnv-stepper-accent); } }

@media (prefers-reduced-motion: reduce) {
  .mnv-stepper { transition: none; }
  .mnv-stepper__mark, .mnv-stepper__ok path, .mnv-stepper__parcel, .mnv-stepper__parcel.is-new, .mnv-stepper__days span { transition: none; }
  .mnv-stepper__item[data-state] .mnv-stepper__mark, .mnv-stepper__item[data-state] .mnv-stepper__mark::after,
  .mnv-stepper__item.is-nope .mnv-stepper__mark, .mnv-stepper__total.is-bump b { animation: none; }
  .mnv-stepper__tick circle, .mnv-stepper__tick path { animation: none; stroke-dashoffset: 0; }
  .mnv-stepper__next[aria-busy="true"]::after { animation-duration: 2s; }
}

