const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = 'mnv-stepper-' + Math.random().toString(36).slice(2, 7);
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const live = $('.mnv-stepper__live');
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const money = (n) => '£' + n.toFixed(2);
const NAMES = ['Pickup', 'Parcels', 'Delivery', 'Review'];
const items = $$('.mnv-stepper__item'), steps = $$('.mnv-stepper__step');
const panels = $$('.mnv-stepper__panel'), done = $('.mnv-stepper__done');
const back = $('.mnv-stepper__back'), next = $('.mnv-stepper__next'), foot = $('.mnv-stepper__foot');
const total = $('.mnv-stepper__total'), list = $('.mnv-stepper__parcels'), add = $('.mnv-stepper__add');
const X = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>';
const WARN = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 8v5M12 16v.2"/></svg>';

/* radio names must be unique per instance or two copies of the component would share one group */
$$('input[name], select[name]').forEach((el) => { el.dataset.key = el.name; el.name = UID + '-' + el.name; });
const field = (key) => $$('[data-key="' + key + '"]');
const pick = (key) => field(key).find((el) => el.checked) || field(key)[0];
panels.forEach((p, i) => { const h = $('.mnv-stepper__ph', p); h.id = UID + '-h' + i; p.setAttribute('aria-labelledby', h.id); p.setAttribute('role', 'group'); });

let cur = 1, reached = 1, booked = false, tried = false;
const errors = new Set();
let parcels = [4.2, 7.5, 12.0];
const band = (w) => (w <= 5 ? 6.4 : w <= 10 ? 8.9 : 13.5);
const okW = (w) => Number.isFinite(w) && w >= 0.1 && w <= 30;

/* ---------- parcels ---------- */
function renderParcels(focusK, fresh) {
  list.innerHTML = parcels.map((w, k) => {
    const id = UID + '-e' + k;
    return '<li class="mnv-stepper__parcel' + (k === fresh ? ' is-new' : '') + '">' +
      '<span class="mnv-stepper__pn">Parcel ' + (k + 1) + '</span>' +
      '<label class="mnv-stepper__kg"><input type="number" inputmode="decimal" min="0.1" max="30" step="0.1" data-k="' + k + '" value="' + (Number.isFinite(w) ? w : '') + '" aria-label="Parcel ' + (k + 1) + ' weight in kilograms" aria-describedby="' + id + '"><span aria-hidden="true">kg</span></label>' +
      '<span class="mnv-stepper__band"></span>' +
      '<button type="button" class="mnv-stepper__rm" data-k="' + k + '" aria-label="Remove parcel ' + (k + 1) + '"' + (parcels.length === 1 ? ' disabled' : '') + '>' + X + '</button>' +
      '<p class="mnv-stepper__err" id="' + id + '" hidden></p></li>';
  }).join('');
  add.disabled = parcels.length >= 5;
  $('span', add).textContent = parcels.length >= 5 ? '5 parcels max' : 'Add parcel';
  checkParcels(false);
  if (focusK != null) { const inp = $('input[data-k="' + focusK + '"]', list); if (inp) inp.focus(); }
}
function checkParcels(show) {
  let bad = 0;
  $$('.mnv-stepper__parcel', list).forEach((li, k) => {
    const w = parcels[k], ok = okW(w), inp = $('input', li), err = $('.mnv-stepper__err', li);
    $('.mnv-stepper__band', li).textContent = ok ? money(band(w)) : '—';
    if (!ok) bad++;
    const vis = !ok && (show || tried);
    inp.setAttribute('aria-invalid', String(vis));
    err.hidden = !vis;
    if (vis) err.innerHTML = WARN + (Number.isFinite(w) && w > 30 ? 'Over 30 kg. Split it across two parcels.' : 'Enter a weight between 0.1 and 30 kg.');
  });
  const kg = parcels.filter(okW).reduce((a, b) => a + b, 0);
  $('.mnv-stepper__weight').textContent = parcels.length + (parcels.length === 1 ? ' parcel · ' : ' parcels · ') +
    (bad ? bad + (bad === 1 ? ' needs a weight' : ' need a weight') : kg.toFixed(1) + ' kg');
  return bad;
}
list.addEventListener('input', (e) => {
  const inp = e.target.closest('input[data-k]');
  if (!inp) return;
  parcels[+inp.dataset.k] = inp.value === '' ? NaN : parseFloat(inp.value);
  const bad = checkParcels(false);
  if (errors.has(1) && !bad) { errors.delete(1); paint(); }
  sum(true);
});
list.addEventListener('click', (e) => {
  const rm = e.target.closest('.mnv-stepper__rm');
  if (!rm || rm.disabled) return;
  const k = +rm.dataset.k;
  const rows = $$('.mnv-stepper__parcel', list);
  const before = rows.map((r) => r.getBoundingClientRect().top);
  parcels.splice(k, 1);
  renderParcels(null);
  if (!RM.matches) {
    $$('.mnv-stepper__parcel', list).forEach((r, i) => {
      const from = before[i >= k ? i + 1 : i];
      const dy = from - r.getBoundingClientRect().top;
      if (dy) r.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)' });
    });
  }
  const f = $('input[data-k="' + Math.min(k, parcels.length - 1) + '"]', list);
  if (f) f.focus();
  if (errors.has(1) && !checkParcels(false)) { errors.delete(1); paint(); }
  sum(true);
  say('Parcel removed. ' + parcels.length + ' left.');
});
add.addEventListener('click', () => {
  if (parcels.length >= 5) return;
  parcels.push(NaN);
  renderParcels(parcels.length - 1, parcels.length - 1);
  sum(true);
});

/* ---------- money ---------- */
function bill() {
  const ok = parcels.filter(okW);
  const p = ok.reduce((a, w) => a + band(w), 0);
  const express = pick('speed').value === 'Express' ? 11 : 0;
  const insure = pick('insure').checked ? 2.4 : 0;
  return { p, n: ok.length, kg: ok.reduce((a, b) => a + b, 0), express, insure, total: Math.round((p + express + insure) * 100) / 100 };
}
let lastTotal = null;
function sum(bump) {
  const b = bill();
  $('b', total).textContent = money(b.total);
  if (bump && lastTotal !== null && lastTotal !== b.total && !RM.matches) { total.classList.remove('is-bump'); void total.offsetWidth; total.classList.add('is-bump'); }
  lastTotal = b.total;
  if (cur === 3 && !booked) $('span', next).textContent = 'Book · ' + money(b.total);
}
root.addEventListener('change', (e) => { if (e.target.matches('input, select')) { sum(true); if (cur === 3) review(); } });

function review() {
  const b = bill(), a = pick('addr'), s = pick('speed');
  $('.mnv-stepper__sum').innerHTML =
    '<div><dt>Collect</dt><dd>' + pick('day').value + ', ' + pick('win').value + '<small>' + a.value + ', ' + a.dataset.line + '</small></dd><button type="button" data-go="0" aria-label="Edit collection">Edit</button></div>' +
    '<div><dt>Parcels</dt><dd>' + b.n + (b.n === 1 ? ' parcel, ' : ' parcels, ') + b.kg.toFixed(1) + ' kg</dd><button type="button" data-go="1" aria-label="Edit parcels">Edit</button></div>' +
    '<div><dt>Delivery</dt><dd>' + s.value + '<small>' + s.dataset.line + (b.insure ? ', insured to £500' : '') + '</small></dd><button type="button" data-go="2" aria-label="Edit delivery">Edit</button></div>';
  $('.mnv-stepper__bill tbody').innerHTML =
    '<tr><td>Parcels (' + b.n + ')</td><td>' + money(b.p) + '</td></tr>' +
    (b.express ? '<tr><td>Express delivery</td><td>' + money(b.express) + '</td></tr>' : '') +
    (b.insure ? '<tr><td>Insurance</td><td>' + money(b.insure) + '</td></tr>' : '') +
    '<tr class="is-total"><td>Total, VAT included</td><td>' + money(b.total) + '</td></tr>';
}
$('.mnv-stepper__sum').addEventListener('click', (e) => { const b = e.target.closest('[data-go]'); if (b) go(+b.dataset.go); });

/* ---------- stepper state ---------- */
function valid(i) {
  if (i !== 1) return true;
  return checkParcels(false) === 0;
}
function paint() {
  items.forEach((li, i) => {
    let st = booked || i < cur ? 'done' : i === cur ? 'current' : i <= reached + 1 ? 'todo' : 'locked';
    if (!booked && errors.has(i)) st = 'error';
    if (!booked && i < cur && !valid(i)) st = 'error';
    if (li.dataset.state !== st) li.dataset.state = st;
    const words = { done: 'Done', current: 'In progress', todo: 'Not started', locked: 'Locked', error: errors.size === 1 ? 'Fix 1 issue' : 'Needs fixing' }[st];
    $('small', li).textContent = words;
    const b = steps[i];
    b.setAttribute('aria-label', 'Step ' + (i + 1) + ', ' + NAMES[i] + ', ' + words.toLowerCase());
    if (i === cur && !booked) b.setAttribute('aria-current', 'step'); else b.removeAttribute('aria-current');
    if (st === 'locked' || booked) b.setAttribute('aria-disabled', 'true'); else b.removeAttribute('aria-disabled');
  });
  root.style.setProperty('--mnv-stepper-p', booked ? 1 : cur / (NAMES.length - 1));
  $('.mnv-stepper__count b').textContent = booked ? 4 : cur + 1;
  $('.mnv-stepper__now').innerHTML = 'Step ' + (cur + 1) + ' of 4 · <b>' + NAMES[cur] + '</b>';
  back.disabled = cur === 0;
  next.classList.toggle('is-book', cur === 3);
  $('span', next).textContent = cur === 3 ? 'Book · ' + money(bill().total) : 'Continue';
}
function swap(from, to, dir) {
  to.hidden = false;
  if (RM.matches || from === to) { if (from !== to) from.hidden = true; return; }
  from.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(' + (-dir * 18) + 'px)' }],
    { duration: 170, easing: 'cubic-bezier(.4,0,1,1)' }).onfinish = () => { from.hidden = true; };
  to.animate([{ opacity: 0, transform: 'translateX(' + (dir * 26) + 'px)', filter: 'blur(2px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
    { duration: 380, delay: 110, easing: 'cubic-bezier(.2,.8,.2,1)', fill: 'backwards' });
}
function go(to) {
  if (booked || to === cur || to < 0 || to > 3) return false;
  if (to > cur) {
    for (let i = cur; i < to; i++) {
      if (!valid(i)) {
        tried = true;
        errors.add(i);
        checkParcels(true);
        if (i !== cur) go(i);
        paint();
        items[i].classList.remove('is-nope');
        void items[i].offsetWidth;
        items[i].classList.add('is-nope');
        const bad = $('[aria-invalid="true"]', list);
        if (bad && i === cur) bad.focus();
        say(NAMES[i] + ' needs fixing before you continue.');
        return false;
      }
    }
    if (to > reached + 1) return false;
  }
  const dir = to > cur ? 1 : -1;
  const from = panels[cur];
  cur = to;
  reached = Math.max(reached, to);
  if (to === 3) review();
  paint();
  swap(from, panels[to], dir);
  $('.mnv-stepper__ph', panels[to]).focus({ preventScroll: true });
  $('.mnv-stepper__stage').scrollTop = 0;
  say('Step ' + (to + 1) + ' of 4, ' + NAMES[to]);
  return true;
}

steps.forEach((b, i) => b.addEventListener('click', () => {
  if (b.getAttribute('aria-disabled') === 'true') {
    const li = items[i];
    li.classList.remove('is-nope');
    void li.offsetWidth;
    li.classList.add('is-nope');
    say(booked ? 'This collection is already booked.' : NAMES[i] + ' unlocks after ' + NAMES[i - 1] + '.');
    return;
  }
  go(i);
}));
$('.mnv-stepper__steps').addEventListener('keydown', (e) => {
  const k = steps.indexOf(e.target);
  if (k < 0) return;
  let n = null;
  if (e.key === 'ArrowRight') n = Math.min(3, k + 1);
  else if (e.key === 'ArrowLeft') n = Math.max(0, k - 1);
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = 3;
  else return;
  e.preventDefault();
  steps[n].focus();
});
back.addEventListener('click', () => go(cur - 1));
next.addEventListener('click', () => {
  if (next.getAttribute('aria-busy') === 'true') return;
  if (cur < 3) { go(cur + 1); return; }
  next.setAttribute('aria-busy', 'true');
  back.disabled = true;
  $('span', next).textContent = 'Booking…';
  say('Booking your collection');
  later(1300, () => {
    booked = true;
    next.removeAttribute('aria-busy');
    const b = bill();
    $('.mnv-stepper__dp').innerHTML = 'Reference <b>BF-48213</b>. A driver collects ' + b.n + (b.n === 1 ? ' parcel' : ' parcels') + ' on ' + pick('day').value + ' between ' + pick('win').value.replace('–', ' and ') + '. Total charged ' + money(b.total) + '.';
    paint();
    swap(panels[3], done, 1);
    foot.hidden = true;
    $('.mnv-stepper__ph', done).focus({ preventScroll: true });
    say('Collection booked. Reference BF-48213.');
  });
});
$('.mnv-stepper__again').addEventListener('click', () => {
  booked = false; tried = false; errors.clear();
  parcels = [4.2, 7.5, 12.0];
  renderParcels(null);
  const from = done;
  cur = 0; reached = 0;
  foot.hidden = false;
  paint();
  sum(false);
  swap(from, panels[0], -1);
  $('.mnv-stepper__ph', panels[0]).focus({ preventScroll: true });
});

renderParcels(null);
paint();
sum(false);

