/* Re-theme with --mnv-dock-backdrop, -screen, -ink and -accent (the bubble), plus -on-accent. */
.mnv-dock {
  --mnv-dock-backdrop: oklch(0.93 0.03 85);
  --mnv-dock-screen: oklch(0.985 0.007 90);
  --mnv-dock-ink: oklch(0.24 0.025 60);
  --mnv-dock-accent: oklch(0.84 0.155 85);
  --mnv-dock-on-accent: oklch(0.27 0.05 70);

  --mnv-dock-bar: color-mix(in oklch, var(--mnv-dock-ink) 96%, var(--mnv-dock-accent));
  --mnv-dock-on-bar: color-mix(in oklch, var(--mnv-dock-screen) 52%, var(--mnv-dock-bar));
  --mnv-dock-line: color-mix(in oklch, var(--mnv-dock-ink) 10%, transparent);
  --mnv-dock-muted: color-mix(in oklch, var(--mnv-dock-ink) 62%, var(--mnv-dock-screen));
  --mnv-dock-faint: color-mix(in oklch, var(--mnv-dock-ink) 40%, var(--mnv-dock-screen));
  --mnv-dock-card: color-mix(in oklch, var(--mnv-dock-ink) 3.5%, var(--mnv-dock-screen));
  --mnv-dock-ring: color-mix(in oklch, var(--mnv-dock-ink) 60%, transparent);
  --mnv-dock-ease: cubic-bezier(.2, .8, .2, 1);
