:where(.mnv-dock) :focus-visible { outline: 2px solid var(--mnv-dock-ring); outline-offset: 2px; }
.mnv-dock svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
