  background: var(--mnv-dock-accent);
  box-shadow: 0 8px 18px -6px color-mix(in oklch, var(--mnv-dock-accent) 70%, var(--mnv-dock-ink)), inset 0 -3px 0 color-mix(in oklch, var(--mnv-dock-ink) 10%, transparent);
  transform: translateX(calc((var(--k) + .5) * 20cqi));
