const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = 'mnv-dock-' + Math.random().toString(36).slice(2, 7);
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const live = $('.mnv-dock__sr');
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const money = (n) => '£' + n.toFixed(2);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const bar = $('.mnv-dock__bar'), tabs = $$('[role="tab"]'), screens = $$('[role="tabpanel"]');
const badge = $('.mnv-dock__badge');
const PLUS = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>';
const MINUS = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12h12"/></svg>';
const TICK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg>';
const BAG = '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M10 17h28l-2.6 21a2 2 0 0 1-2 1.8H14.6a2 2 0 0 1-2-1.8Z"/><path d="M18 17v-3a6 6 0 0 1 12 0v3"/></svg>';
const DONE = '<svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="16"/><path d="m16.5 24.5 5 5 10-11"/></svg>';

const P = {
  bread: { n: 'Sourdough loaf', d: '800 g, baked this morning', p: 3.4, h: 70 },
  clem: { n: 'Clementines', d: '600 g net, Spanish', p: 2.1, h: 60 },
  oat: { n: 'Oat drink', d: '1 litre, unsweetened', p: 1.65, h: 95 },
  feta: { n: 'Barrel-aged feta', d: '200 g, PDO', p: 2.85, h: 140 },
};
const LISTS = [
  { n: 'Breakfast run', ids: ['bread', 'oat'] },
  { n: 'Mezze night', ids: ['feta', 'clem', 'bread'] },
];
let basket = { bread: 1, clem: 2 };
let cur = 0, savedLoaded = false, ordered = null;

tabs.forEach((t, i) => {
  t.id = UID + '-t' + i;
  screens[i].id = UID + '-p' + i;
  t.setAttribute('aria-controls', screens[i].id);
  screens[i].setAttribute('aria-labelledby', t.id);
});

/* ---------- product rows ---------- */
function rows(ul, ids) {
  ul.innerHTML = ids.map((id) => {
    const p = P[id];
    return '<li class="mnv-dock__item" data-id="' + id + '"><span class="mnv-dock__art" style="--h:' + p.h + '" aria-hidden="true"></span>' +
      '<span><b>' + esc(p.n) + '</b><small>' + esc(p.d) + '</small></span>' +
      '<span class="mnv-dock__buy"><em>' + money(p.p) + '</em>' +
      '<button type="button" class="mnv-dock__add" data-id="' + id + '" aria-label="Add ' + esc(p.n) + ' to basket">' + PLUS + TICK + '</button></span></li>';
  }).join('');
}
$$('.mnv-dock__picks').forEach((ul) => rows(ul, ul.dataset.list.split(' ')));
root.addEventListener('click', (e) => {
  const add = e.target.closest('.mnv-dock__add');
  if (!add) return;
  put(add.dataset.id, 1);
  add.classList.add('is-done');
  later(900, () => add.classList.remove('is-done'));
  say(P[add.dataset.id].n + ' added. ' + count() + ' items in basket.');
});

/* ---------- basket ---------- */
const count = () => Object.values(basket).reduce((a, b) => a + b, 0);
function put(id, n) {
  basket[id] = Math.max(0, (basket[id] || 0) + n);
  if (!basket[id]) delete basket[id];
  ordered = null;
  paintBadge(true);
  paintBasket();
}
function paintBadge(bump) {
  const c = count();
  badge.textContent = c ? String(c) : '';
  tabs[2].setAttribute('aria-label', 'Basket, ' + (c ? c + (c === 1 ? ' item' : ' items') : 'empty'));
  if (bump && c && !RM.matches) { badge.classList.remove('is-bump'); void badge.offsetWidth; badge.classList.add('is-bump'); }
}
function paintBasket() {
  const box = $('.mnv-dock__basket');
  if (ordered) {
    box.innerHTML = '<div class="mnv-dock__empty is-ok">' + DONE + '<b>Order LD-20917 placed</b><span>' + ordered + ' items arriving Thursday between 18:00 and 19:00.</span><button type="button" data-go="0">Keep shopping</button></div>';
    return;
  }
  const ids = Object.keys(basket);
  if (!ids.length) {
    box.innerHTML = '<div class="mnv-dock__empty">' + BAG + '<b>Your basket is empty</b><span>Picked for you is a good place to start.</span><button type="button" data-go="0">Browse picks</button></div>';
    return;
  }
  const sub = ids.reduce((a, id) => a + P[id].p * basket[id], 0);
  const fee = sub >= 40 ? 0 : 1.5;
  box.innerHTML = ids.map((id) => {
    const p = P[id], q = basket[id];
    return '<div class="mnv-dock__line"><span><b>' + esc(p.n) + '</b><small>' + money(p.p) + ' each</small></span>' +
      '<span class="mnv-dock__qty"><button type="button" data-q="-1" data-id="' + id + '" aria-label="One fewer ' + esc(p.n) + '">' + MINUS + '</button><span aria-live="polite">' + q + '</span>' +
      '<button type="button" data-q="1" data-id="' + id + '" aria-label="One more ' + esc(p.n) + '">' + PLUS + '</button></span><em>' + money(p.p * q) + '</em></div>';
  }).join('') +
    '<div class="mnv-dock__totals"><div><span>Subtotal</span><span>' + money(sub) + '</span></div><div><span>Delivery' + (fee ? ', free over £40' : '') + '</span><span>' + (fee ? money(fee) : 'Free') + '</span></div>' +
    '<div><span>Total</span><span>' + money(sub + fee) + '</span></div></div>' +
    '<button type="button" class="mnv-dock__cta">Checkout · ' + money(sub + fee) + '</button>';
}
$('.mnv-dock__basket').addEventListener('click', (e) => {
  const q = e.target.closest('[data-q]');
  if (q) { put(q.dataset.id, +q.dataset.q); const again = $('[data-q="' + q.dataset.q + '"][data-id="' + q.dataset.id + '"]'); if (again) again.focus(); return; }
  const go = e.target.closest('[data-go]');
  if (go) { select(+go.dataset.go, true); return; }
  const cta = e.target.closest('.mnv-dock__cta');
  if (cta && cta.getAttribute('aria-busy') !== 'true') {
    cta.setAttribute('aria-busy', 'true');
    cta.textContent = 'Placing order…';
    later(900, () => {
      const n = count();
      basket = {};
      ordered = n;
      paintBadge(false);
      paintBasket();
      say('Order placed. ' + n + ' items arriving Thursday.');
    });
  }
});

/* ---------- search ---------- */
const sInput = $('.mnv-dock__search input'), results = $('.mnv-dock__results'), none = $('.mnv-dock__none');
function search() {
  const q = sInput.value.trim().toLowerCase();
  const ids = Object.keys(P).filter((id) => !q || P[id].n.toLowerCase().includes(q) || P[id].d.toLowerCase().includes(q));
  rows(results, ids);
  none.hidden = ids.length > 0;
  $('q', none).textContent = sInput.value.trim();
}
sInput.addEventListener('input', search);
$('.mnv-dock__recent').addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  sInput.value = b.textContent;
  search();
  sInput.focus();
});

/* ---------- saved lists (loaded on first visit) ---------- */
function paintSaved() {
  $('.mnv-dock__lists').innerHTML = LISTS.map((l, i) => {
    const total = l.ids.reduce((a, id) => a + P[id].p, 0);
    return '<div class="mnv-dock__list"><span><b>' + esc(l.n) + '</b><small>' + l.ids.map((id) => P[id].n).join(', ') + ' · ' + money(total) + '</small></span>' +
      '<button type="button" data-list="' + i + '">Add all ' + l.ids.length + '</button></div>';
  }).join('');
}
function loadSaved() {
  const box = $('.mnv-dock__lists');
  box.setAttribute('aria-busy', 'true');
  box.innerHTML = [0, 1, 2].map((i) => '<div class="mnv-dock__skel" style="--i:' + i + '"></div>').join('');
  later(700, () => { savedLoaded = true; box.removeAttribute('aria-busy'); paintSaved(); });
}
$('.mnv-dock__lists').addEventListener('click', (e) => {
  const b = e.target.closest('[data-list]');
  if (!b || b.disabled) return;
  const l = LISTS[+b.dataset.list];
  l.ids.forEach((id) => { basket[id] = (basket[id] || 0) + 1; });
  ordered = null;
  paintBadge(true);
  paintBasket();
  b.disabled = true;
  b.textContent = 'Added';
  say(l.n + ' added. ' + count() + ' items in basket.');
  later(1600, () => { b.disabled = false; b.textContent = 'Add all ' + l.ids.length; });
});

/* ---------- the tab bar ---------- */
function select(k, focus) {
  if (k === cur && !focus) return;
  const dir = k > cur ? 1 : -1;
  cur = k;
  tabs.forEach((t, i) => {
    t.setAttribute('aria-selected', String(i === k));
    t.tabIndex = i === k ? 0 : -1;
  });
  screens.forEach((s, i) => {
    if (i === k) { s.style.setProperty('--dir', dir); s.hidden = false; s.scrollTop = 0; } else s.hidden = true;
  });
  bar.style.setProperty('--k', k);
  if (focus) tabs[k].focus();
  if (k === 3 && !savedLoaded) loadSaved();
}
tabs.forEach((t, i) => t.addEventListener('click', () => select(i, false)));
$('.mnv-dock__tabs').addEventListener('keydown', (e) => {
  const k = tabs.indexOf(e.target);
  if (k < 0) return;
  let n = null;
  if (e.key === 'ArrowRight') n = (k + 1) % tabs.length;
  else if (e.key === 'ArrowLeft') n = (k - 1 + tabs.length) % tabs.length;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = tabs.length - 1;
  else return;
  e.preventDefault();
  select(n, true);
});

paintBadge(false);
paintBasket();
cur = -1;
select(0, false);

