@property --mnv-orgs-hue {
  syntax: "<number>";
  inherits: true;
  initial-value: 35;
}

/* Every colour hangs off --mnv-orgs-hue; re-theme the neutrals with -l (lightness) and -c (chroma). */
.mnv-orgs {
  --mnv-orgs-hue: 35;
  --mnv-orgs-l: 0.185;
  --mnv-orgs-c: 0.014;

  --mnv-orgs-bg: oklch(var(--mnv-orgs-l) var(--mnv-orgs-c) var(--mnv-orgs-hue));
  --mnv-orgs-panel: oklch(calc(var(--mnv-orgs-l) + .045) calc(var(--mnv-orgs-c) + .004) var(--mnv-orgs-hue));
  --mnv-orgs-ink: oklch(0.95 0.012 var(--mnv-orgs-hue));
  --mnv-orgs-accent: oklch(0.76 0.135 var(--mnv-orgs-hue));
  --mnv-orgs-danger: oklch(0.7 0.16 25);
  --mnv-orgs-line: color-mix(in oklch, var(--mnv-orgs-ink) 9%, transparent);
  --mnv-orgs-muted: color-mix(in oklch, var(--mnv-orgs-ink) 62%, var(--mnv-orgs-bg));
  --mnv-orgs-faint: color-mix(in oklch, var(--mnv-orgs-ink) 38%, var(--mnv-orgs-bg));
  --mnv-orgs-hover: color-mix(in oklch, var(--mnv-orgs-ink) 6%, transparent);
  --mnv-orgs-sel: color-mix(in oklch, var(--mnv-orgs-accent) 16%, transparent);
  --mnv-orgs-ring: color-mix(in oklch, var(--mnv-orgs-accent) 80%, transparent);
  --mnv-orgs-ease: cubic-bezier(.22, 1, .36, 1);

  position: relative;
  container-type: inline-size;
  color-scheme: dark;
  box-sizing: border-box;
  width: 100%;
  height: 500px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top" "body" "me";
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  color: var(--mnv-orgs-ink);
  background:
    radial-gradient(90% 50% at 0% 0%, color-mix(in oklch, var(--mnv-orgs-accent) 14%, transparent), transparent 70%),
    var(--mnv-orgs-bg);
  box-shadow: 0 0 0 1px var(--mnv-orgs-line), 0 24px 50px -28px oklch(0 0 0 / .8);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  transition: --mnv-orgs-hue .9s cubic-bezier(.65, 0, .35, 1);
}
:where(.mnv-orgs) *, :where(.mnv-orgs) *::before, :where(.mnv-orgs) *::after { box-sizing: border-box; }
:where(.mnv-orgs) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnv-orgs) :focus-visible { outline: 2px solid var(--mnv-orgs-ring); outline-offset: 2px; }
.mnv-orgs svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.mnv-orgs__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* tiles: each workspace keeps its own hue in --h */
.mnv-orgs__tile, .mnv-orgs__otile {
  display: grid; place-items: center; flex: none; border-radius: 9px;
  font: 750 12px/1 system-ui, sans-serif; letter-spacing: -.02em; color: oklch(0.2 0.04 var(--h));
  background: linear-gradient(140deg, oklch(0.8 0.13 var(--h)), oklch(0.64 0.16 calc(var(--h) + 28)));
  box-shadow: inset 0 0 0 1px oklch(1 0 0 / .18), inset 0 -2px 0 oklch(0 0 0 / .12);
}
.mnv-orgs__tile { width: 36px; height: 36px; font-size: 13px; transition: scale .4s var(--mnv-orgs-ease); }

/* ---------- trigger ---------- */
.mnv-orgs__top { grid-area: top; padding: 10px 10px 6px; }
.mnv-orgs__trigger {
  width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 7px 8px 7px 7px; border-radius: 12px; text-align: left;
  transition: background-color .2s;
  &:hover, &[aria-expanded="true"] { background: var(--mnv-orgs-hover); }
  &:active .mnv-orgs__tile { scale: .94; }
  &[aria-busy="true"] .mnv-orgs__updown { opacity: 0; }
  &[aria-busy="true"]::after {
    content: ""; position: absolute; right: 18px; width: 14px; height: 14px; border-radius: 50%;
    border: 2px solid var(--mnv-orgs-line); border-top-color: var(--mnv-orgs-accent); animation: mnv-orgs-spin .7s linear infinite;
  }
  position: relative;
}
.mnv-orgs__who { display: grid; min-width: 0; }
.mnv-orgs__name { font-size: 14px; font-weight: 700; letter-spacing: -.015em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnv-orgs__meta { font-size: 11.5px; color: var(--mnv-orgs-muted); font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnv-orgs__updown { color: var(--mnv-orgs-faint); transition: opacity .2s; }
.mnv-orgs.is-swapping :is(.mnv-orgs__who, .mnv-orgs__body) { animation: mnv-orgs-swap .5s var(--mnv-orgs-ease) both; }

/* ---------- body ---------- */
.mnv-orgs__body { grid-area: body; min-height: 0; overflow: auto; padding: 4px 10px 12px; scrollbar-width: none; }
.mnv-orgs__nav { display: grid; gap: 1px; }
.mnv-orgs__link {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  height: 34px; padding: 0 10px; border-radius: 9px; color: var(--mnv-orgs-muted); text-decoration: none;
  transition: background-color .2s, color .2s;
  & svg { width: 17px; height: 17px; }
  & span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & em { font-style: normal; font-size: 11.5px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--mnv-orgs-faint); }
  &:hover { background: var(--mnv-orgs-hover); color: var(--mnv-orgs-ink); }
  &[aria-current="page"] {
    color: var(--mnv-orgs-ink); background: var(--mnv-orgs-sel); font-weight: 600;
    & svg { color: var(--mnv-orgs-accent); }
    & em { color: var(--mnv-orgs-accent); }
  }
  &:focus-visible { outline-offset: -2px; }
}
.mnv-orgs__label { margin: 16px 10px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--mnv-orgs-faint); }
.mnv-orgs__projects { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.mnv-orgs__proj {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 7px 10px; border-radius: 9px; font-size: 12.5px; color: var(--mnv-orgs-muted);
  & i { width: 8px; height: 8px; border-radius: 3px; background: oklch(0.74 0.13 calc(var(--mnv-orgs-hue) + var(--d, 0))); }
  & span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & em { font-style: normal; font-size: 11px; font-variant-numeric: tabular-nums; color: var(--mnv-orgs-faint); display: flex; align-items: center; gap: 6px; }
  & em::before { content: ""; width: 34px; height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--mnv-orgs-accent) calc(var(--p) * 1%), var(--mnv-orgs-line) 0); }
}
.mnv-orgs__usage {
  margin: 16px 4px 0; padding: 11px 12px 12px; border-radius: 12px;
  background: color-mix(in oklch, var(--mnv-orgs-ink) 3.5%, transparent); box-shadow: inset 0 0 0 1px var(--mnv-orgs-line);
  & p { margin: 0; }
}
.mnv-orgs__uhead {
  display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 12px;
  & b { font-weight: 650; }
  & span { font-variant-numeric: tabular-nums; color: var(--mnv-orgs-muted); font-size: 11.5px; }
}
.mnv-orgs__meter {
  display: block; height: 5px; margin: 8px 0 7px; border-radius: 3px; overflow: hidden; background: var(--mnv-orgs-line);
  & i { display: block; height: 100%; border-radius: inherit; background: var(--mnv-orgs-accent); transform-origin: 0 50%; transform: scaleX(var(--u, 0)); transition: transform .8s var(--mnv-orgs-ease), background-color .3s; }
}
.mnv-orgs__uhint { font-size: 11.5px; color: var(--mnv-orgs-faint); text-wrap: pretty; }
.mnv-orgs__usage.is-full {
  & .mnv-orgs__meter i { background: oklch(0.8 0.14 75); }
  & .mnv-orgs__uhint { color: oklch(0.82 0.12 75); }
}
.mnv-orgs__skel {
  height: 34px; border-radius: 9px; margin-bottom: 2px;
  background: linear-gradient(100deg, var(--mnv-orgs-hover) 30%, color-mix(in oklch, var(--mnv-orgs-ink) 11%, transparent) 50%, var(--mnv-orgs-hover) 70%) 0 0 / 300% 100%;
  animation: mnv-orgs-shimmer 1s linear infinite; animation-delay: calc(var(--i) * -110ms);
}

.mnv-orgs__me {
  grid-area: me; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 10px 16px 12px; border-top: 1px solid var(--mnv-orgs-line);
  & b { display: block; font-size: 12.5px; font-weight: 650; }
  & small { display: block; font-size: 11px; color: var(--mnv-orgs-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}
.mnv-orgs__avatar { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; font-size: 11px; font-weight: 700; color: oklch(0.25 0.05 150); background: oklch(0.82 0.09 150); }
.mnv-orgs__online { width: 8px; height: 8px; border-radius: 50%; background: oklch(0.75 0.16 150); box-shadow: 0 0 0 3px color-mix(in oklch, oklch(0.75 0.16 150) 22%, transparent); }

/* ---------- switcher panel ---------- */
.mnv-orgs__pop {
  position: absolute; top: 60px; left: 8px; right: 8px; z-index: 5; max-height: calc(100% - 70px);
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto;
  border-radius: 14px; background: var(--mnv-orgs-panel);
  box-shadow: 0 0 0 1px var(--mnv-orgs-line), 0 22px 44px -12px oklch(0 0 0 / .75);
  transform-origin: 50% 0;
  opacity: 1; scale: 1; translate: 0 0;
  transition: opacity .18s, scale .28s var(--mnv-orgs-ease), translate .28s var(--mnv-orgs-ease), display .28s allow-discrete;
  @starting-style { opacity: 0; scale: .97; translate: 0 -6px; }
  &[hidden] { display: none; opacity: 0; scale: .98; translate: 0 -4px; }
}
.mnv-orgs__find {
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 8px;
  margin: 4px 6px 6px; padding: 0 10px; height: 40px; color: var(--mnv-orgs-faint);
  border-bottom: 1px solid var(--mnv-orgs-line);
  & input { border: 0; outline: none; background: none; min-width: 0; font: inherit; font-size: 13px; color: var(--mnv-orgs-ink); }
  & input::placeholder { color: var(--mnv-orgs-faint); }
}
.mnv-orgs__scroll { min-height: 0; overflow: auto; padding: 0 6px 6px; scrollbar-width: thin; scrollbar-color: var(--mnv-orgs-line) transparent; }
.mnv-orgs__group { margin: 6px 8px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--mnv-orgs-faint); }
.mnv-orgs__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
.mnv-orgs__opt {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 6px 8px; border-radius: 9px; cursor: pointer;
  transition: background-color .15s, opacity .3s, translate .4s var(--mnv-orgs-ease);
  transition-delay: 0s, calc(var(--i, 0) * 30ms), calc(var(--i, 0) * 30ms);
  @starting-style { opacity: 0; translate: 0 -4px; }
  & .mnv-orgs__otile { width: 30px; height: 30px; border-radius: 8px; font-size: 11px; }
  & b { display: block; font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { display: block; font-size: 11px; color: var(--mnv-orgs-faint); font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & kbd { font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: var(--mnv-orgs-faint); }
  & .mnv-orgs__check { display: none; color: var(--mnv-orgs-accent); }
  &[aria-selected="true"] { & .mnv-orgs__check { display: block; } & kbd { display: none; } }
  &.is-active { background: var(--mnv-orgs-hover); box-shadow: inset 0 0 0 1px var(--mnv-orgs-line); }
  &:hover { background: var(--mnv-orgs-hover); }
  &[aria-disabled="true"] {
    cursor: not-allowed;
    & .mnv-orgs__otile { filter: grayscale(1) brightness(.75); }
    & b { color: var(--mnv-orgs-muted); }
    & small { color: var(--mnv-orgs-danger); }
  }
  &.is-nope { animation: mnv-orgs-nope .4s var(--mnv-orgs-ease); }
}
.mnv-orgs__tag { font: 650 9.5px/1 system-ui, sans-serif; letter-spacing: .06em; text-transform: uppercase; padding: 4px 6px; border-radius: 5px; color: var(--mnv-orgs-danger); background: color-mix(in oklch, var(--mnv-orgs-danger) 14%, transparent); white-space: nowrap; }
.mnv-orgs__none {
  margin: 8px; padding: 10px; border-radius: 9px; font-size: 12.5px; color: var(--mnv-orgs-muted); text-align: center; text-wrap: balance;
  background: var(--mnv-orgs-hover);
  &[hidden] { display: none; }
  & q { color: var(--mnv-orgs-ink); }
}
.mnv-orgs__invite {
  &:empty { display: none; }
  & .mnv-orgs__inv {
    display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 10px; align-items: center; margin-top: 4px;
    padding: 9px 8px; border-radius: 10px; background: color-mix(in oklch, var(--mnv-orgs-accent) 7%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-orgs-accent) 22%, transparent);
    transition: opacity .3s, scale .3s var(--mnv-orgs-ease);
  }
  & .mnv-orgs__otile { width: 30px; height: 30px; border-radius: 8px; font-size: 11px; }
  & b { display: block; font-size: 12.5px; font-weight: 600; }
  & small { display: block; font-size: 11px; color: var(--mnv-orgs-muted); }
  & .mnv-orgs__acts { grid-column: 2; display: flex; gap: 6px; margin-top: 4px; }
  & .mnv-orgs__acts button { padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--mnv-orgs-line); transition: background-color .15s, filter .15s; }
  & .mnv-orgs__acts button:hover { background: var(--mnv-orgs-hover); }
  & .mnv-orgs__acts .is-yes { color: oklch(0.22 0.04 var(--mnv-orgs-hue)); background: var(--mnv-orgs-accent); box-shadow: none; }
  & .mnv-orgs__acts .is-yes:hover { background: var(--mnv-orgs-accent); filter: brightness(1.1); }
  & .mnv-orgs__acts [aria-busy="true"] { opacity: .7; cursor: progress; }
}
.mnv-orgs__note {
  margin: 0 8px; font-size: 11.5px; color: var(--mnv-orgs-danger); text-wrap: pretty;
  &:empty { display: none; }
  &:not(:empty) { margin-bottom: 6px; padding: 7px 9px; border-radius: 8px; background: color-mix(in oklch, var(--mnv-orgs-danger) 10%, transparent); }
}
.mnv-orgs__foot { border-top: 1px solid var(--mnv-orgs-line); padding: 6px; }
.mnv-orgs__create {
  width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px; border-radius: 9px; color: var(--mnv-orgs-muted); font-size: 12.5px; font-weight: 550;
  & svg { width: 30px; height: 30px; padding: 7px; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--mnv-orgs-line); }
  &:hover { background: var(--mnv-orgs-hover); color: var(--mnv-orgs-ink); }
  &[hidden] { display: none; }
}
.mnv-orgs__new {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; padding: 2px;
  &[hidden] { display: none; }
  & input { min-width: 0; height: 34px; padding: 0 10px; border-radius: 8px; border: 0; outline: none; font: inherit; font-size: 12.5px; color: var(--mnv-orgs-ink); background: var(--mnv-orgs-bg); box-shadow: inset 0 0 0 1px var(--mnv-orgs-line); }
  & input:focus-visible { box-shadow: inset 0 0 0 1.5px var(--mnv-orgs-ring); }
  & button { padding: 0 12px; border-radius: 8px; font-weight: 650; font-size: 12.5px; color: oklch(0.22 0.04 var(--mnv-orgs-hue)); background: var(--mnv-orgs-accent); }
  & button:disabled { opacity: .45; cursor: not-allowed; }
  transition: opacity .2s, translate .3s var(--mnv-orgs-ease);
  @starting-style { opacity: 0; translate: 0 4px; }
}

@container (max-width: 290px) {
  .mnv-orgs__opt kbd, .mnv-orgs__proj em::before { display: none; }
  .mnv-orgs__me small { display: none; }
}

@keyframes mnv-orgs-spin { to { rotate: 360deg; } }
@keyframes mnv-orgs-shimmer { to { background-position: -300% 0; } }
