  .mnv-orgs__pop, .mnv-orgs__opt, .mnv-orgs__new { transition: none; }
  .mnv-orgs.is-swapping :is(.mnv-orgs__who, .mnv-orgs__body), .mnv-orgs__opt.is-nope, .mnv-orgs__usage {
  margin: 16px 4px 0; padding: 11px 12px 12px; border-radius: 12px;
  background: color-mix(in oklch, var(--mnv-orgs-ink) 3.5%, transparent); box-shadow: inset 0 0 0 1px var(--mnv-orgs-line);
