}
.mnv-orgs__uhead {
  display: flex; justify-content: space-between; align-items: baseline; gap: 8px; font-size: 12px;
  & b { font-weight: 650; }
  & span { font-variant-numeric: tabular-nums; color: var(--mnv-orgs-muted); font-size: 11.5px; }
}
.mnv-orgs__meter {
  display: block; height: 5px; margin: 8px 0 7px; border-radius: 3px; overflow: hidden; background: var(--mnv-orgs-line);
  & i { display: block; height: 100%; border-radius: inherit; background: var(--mnv-orgs-accent); transform-origin: 0 50%; transform: scaleX(var(--u, 0)); transition: transform .8s var(--mnv-orgs-ease), background-color .3s; }
