const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = 'mnv-orgs-' + Math.random().toString(36).slice(2, 7);
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const live = $('.mnv-orgs__sr');
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const trigger = $('.mnv-orgs__trigger'), pop = $('.mnv-orgs__pop'), input = $('.mnv-orgs__find input');
const listbox = $('.mnv-orgs__list'), none = $('.mnv-orgs__none'), note = $('.mnv-orgs__note'), invite = $('.mnv-orgs__invite');
const createBtn = $('.mnv-orgs__create'), form = $('.mnv-orgs__new'), formInput = $('input', form);
const CHECK = '<svg class="mnv-orgs__check" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg>';
const MAC = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);

const WS = [
  { id: 'kittiwake', n: 'Kittiwake Studio', ini: 'KS', h: 35, role: 'Owner', plan: 'Pro', m: 14, seats: 15, inbox: 12, mine: 5, mail: 'kittiwake.studio',
    projects: [['Harbourside rebrand', 72], ['Ferry timetable app', 41], ['Annual report 2026', 18]] },
  { id: 'ashby', n: 'Ashby & Rowe', ini: 'AR', h: 250, role: 'Admin', plan: 'Business', m: 86, seats: 100, inbox: 31, mine: 9, mail: 'ashbyrowe.law',
    projects: [['Client portal v3', 64], ['Matter intake', 88], ['Billing migration', 27]] },
  { id: 'quillon', n: 'Quillon Labs', ini: 'QL', h: 150, role: 'Member', plan: 'Free', m: 3, seats: 3, inbox: 2, mine: 1, mail: 'quillon.dev',
    projects: [['Sensor firmware', 55], ['Grant application', 90]] },
  { id: 'ottoline', n: 'Ottoline Press', ini: 'OP', h: 350, role: 'Member', plan: 'Pro', m: 22, seats: 25, inbox: 7, mine: 0, mail: 'ottolinepress.co',
    projects: [['Spring catalogue', 36], ['Reprint queue', 12], ['Author portal', 60]] },
  { id: 'brack', n: 'Brackwater Co-op', ini: 'BC', h: 85, role: 'Member', plan: 'Pro', m: 9, paused: 'Payment failed on 28 Sep. Ask an owner to update billing to reopen it.' },
];
let invitation = { id: 'saltmarsh', n: 'Saltmarsh Analytics', ini: 'SA', h: 195, role: 'Member', plan: 'Business', m: 41, seats: 50, inbox: 4, mine: 0, by: 'Tomás Varga', mail: 'saltmarsh.io',
  projects: [['Tide model', 47], ['Q4 dashboards', 73]] };
let current = 'kittiwake', hue = 35, activeIdx = 0, shown = [];
const byId = (id) => WS.find((w) => w.id === id);

pop.id = UID + '-pop';
listbox.id = UID + '-list';
trigger.setAttribute('aria-controls', pop.id);
input.setAttribute('aria-controls', listbox.id);

/* ---------- shell ---------- */
function paintShell(w) {
  const tile = $('.mnv-orgs__tile');
  tile.style.setProperty('--h', w.h);
  tile.textContent = w.ini;
  $('.mnv-orgs__name').textContent = w.n;
  $('.mnv-orgs__meta').textContent = w.plan + ' · ' + w.m + (w.m === 1 ? ' member' : ' members');
  trigger.setAttribute('aria-label', 'Workspace: ' + w.n + '. Switch workspace');
  $$('[data-count]').forEach((em) => {
    const v = w[em.dataset.count];
    em.textContent = v ? String(v) : '';
  });
  $('.mnv-orgs__projects').innerHTML = w.projects.map((p, i) =>
    '<li class="mnv-orgs__proj" style="--d:' + i * 55 + ';--p:' + p[1] + '"><i aria-hidden="true"></i><span>' + esc(p[0]) + '</span><em aria-label="' + p[1] + ' percent complete">' + p[1] + '%</em></li>').join('');
  $('.mnv-orgs__me small').textContent = 'ines@' + w.mail;
  const left = w.seats - w.m, full = left <= 0;
  $('.mnv-orgs__useats').textContent = w.m + ' of ' + w.seats + ' used';
  const meter = $('.mnv-orgs__meter');
  meter.setAttribute('aria-valuemax', w.seats);
  meter.setAttribute('aria-valuenow', w.m);
  meter.style.setProperty('--u', Math.min(1, w.m / w.seats));
  $('.mnv-orgs__usage').classList.toggle('is-full', full);
  $('.mnv-orgs__uhint').textContent = full ? 'The ' + w.plan + ' plan is full. Upgrade to invite anyone else.' : left + (left === 1 ? ' seat' : ' seats') + ' left on ' + w.plan + '.';
}
function setHue(target) {
  /* move the short way round the colour wheel: keep the running value continuous */
  let d = ((target - hue) % 360 + 540) % 360 - 180;
  hue += d;
  root.style.setProperty('--mnv-orgs-hue', hue);
}

/* ---------- options ---------- */
function optionHTML(w, i) {
  const sel = w.id === current;
  const sub = w.paused ? '<small>Billing paused</small>' : '<small>' + w.role + ' · ' + w.plan + ' · ' + w.m + (w.m === 1 ? ' member' : ' members') + '</small>';
  const k = WS.indexOf(w) + 1;
  return '<li class="mnv-orgs__opt" role="option" id="' + UID + '-o-' + w.id + '" data-id="' + w.id + '" style="--i:' + i + '" aria-selected="' + sel + '"' + (w.paused ? ' aria-disabled="true"' : '') + '>' +
    '<span class="mnv-orgs__otile" style="--h:' + w.h + '" aria-hidden="true">' + w.ini + '</span>' +
    '<span><b>' + esc(w.n) + '</b>' + sub + '</span>' +
    (w.paused ? '<span class="mnv-orgs__tag">Paused</span>' : k <= 9 ? '<kbd aria-hidden="true">' + (MAC ? '⌥' : 'Alt+') + k + '</kbd>' + CHECK : CHECK) + '</li>';
}
function renderList() {
  const q = input.value.trim().toLowerCase();
  shown = WS.filter((w) => !q || w.n.toLowerCase().includes(q));
  listbox.innerHTML = shown.map(optionHTML).join('');
  none.hidden = shown.length > 0;
  $('q', none).textContent = input.value.trim();
  const ci = shown.findIndex((w) => w.id === current);
  setActive(q ? 0 : Math.max(0, ci));
  renderInvite(q);
}
function setActive(i) {
  const opts = $$('[role="option"]', listbox);
  if (!opts.length) { input.removeAttribute('aria-activedescendant'); activeIdx = -1; return; }
  activeIdx = (i + opts.length) % opts.length;
  opts.forEach((o, k) => o.classList.toggle('is-active', k === activeIdx));
  input.setAttribute('aria-activedescendant', opts[activeIdx].id);
  const o = opts[activeIdx], sc = $('.mnv-orgs__scroll');
  const r = o.getBoundingClientRect(), s = sc.getBoundingClientRect();
  if (r.top < s.top) sc.scrollTop -= s.top - r.top + 4;
  else if (r.bottom > s.bottom) sc.scrollTop += r.bottom - s.bottom + 4;
}
function renderInvite(q) {
  if (!invitation || (q && !invitation.n.toLowerCase().includes(q))) { invite.innerHTML = ''; return; }
  const w = invitation;
  invite.innerHTML = '<p class="mnv-orgs__group">Invitation</p><div class="mnv-orgs__inv"><span class="mnv-orgs__otile" style="--h:' + w.h + '" aria-hidden="true">' + w.ini + '</span>' +
    '<span><b>' + esc(w.n) + '</b><small>' + esc(w.by) + ' invited you as ' + w.role.toLowerCase() + '</small></span>' +
    '<span class="mnv-orgs__acts"><button type="button" class="is-yes" data-inv="yes">Accept</button><button type="button" data-inv="no">Decline</button></span></div>';
}

/* ---------- open / close ---------- */
function open(fromEnd) {
  if (!pop.hidden) return;
  note.textContent = '';
  input.value = '';
  pop.hidden = false;
  trigger.setAttribute('aria-expanded', 'true');
  renderList();
  if (fromEnd) setActive(shown.length - 1);
  input.focus();
}
let closedAt = 0;
function close(refocus) {
  if (pop.hidden) return;
  closedAt = performance.now();
  pop.hidden = true;
  trigger.setAttribute('aria-expanded', 'false');
  form.hidden = true;
  createBtn.hidden = false;
  if (refocus) trigger.focus();
}
/* the press that blurs the panel already closed it; do not reopen on the click that follows */
trigger.addEventListener('click', () => { if (performance.now() - closedAt < 300) return; if (pop.hidden) open(false); else close(true); });
trigger.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); open(e.key === 'ArrowUp'); }
});
/* keep focus in the combobox while the pointer picks an option */
pop.addEventListener('mousedown', (e) => { if (!e.target.closest('input, button')) e.preventDefault(); });
pop.addEventListener('focusout', (e) => {
  if (!pop.contains(e.relatedTarget) && e.relatedTarget !== trigger) close(false);
});
pop.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(true); }
});

/* ---------- switching ---------- */
function choose(id) {
  const w = byId(id);
  if (!w) return;
  if (w.paused) {
    const li = $('[data-id="' + id + '"]', listbox);
    if (li) { li.classList.remove('is-nope'); void li.offsetWidth; li.classList.add('is-nope'); }
    note.textContent = w.n + ' is paused. ' + w.paused;
    return;
  }
  close(true);
  if (id === current) return;
  current = id;
  trigger.setAttribute('aria-busy', 'true');
  const body = $('.mnv-orgs__body');
  body.setAttribute('aria-busy', 'true');
  $('.mnv-orgs__projects').innerHTML = [0, 1, 2].map((i) => '<li class="mnv-orgs__skel" style="--i:' + i + '" aria-hidden="true"></li>').join('');
  setHue(w.h);
  say('Switching to ' + w.n);
  later(RM.matches ? 200 : 650, () => {
    trigger.removeAttribute('aria-busy');
    body.removeAttribute('aria-busy');
    paintShell(w);
    if (!RM.matches) { root.classList.remove('is-swapping'); void root.offsetWidth; root.classList.add('is-swapping'); }
    say('Now in ' + w.n);
  });
}
listbox.addEventListener('click', (e) => { const o = e.target.closest('[role="option"]'); if (o) choose(o.dataset.id); });
listbox.addEventListener('pointermove', (e) => {
  const o = e.target.closest('[role="option"]');
  if (o) { const k = $$('[role="option"]', listbox).indexOf(o); if (k !== activeIdx) setActive(k); }
});
input.addEventListener('input', () => { note.textContent = ''; renderList(); });
input.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown') setActive(activeIdx + 1);
  else if (e.key === 'ArrowUp') setActive(activeIdx - 1);
  else if (e.key === 'Home' && !input.value) setActive(0);
  else if (e.key === 'End' && !input.value) setActive(-1);
  else if (e.key === 'Enter') {
    const opts = $$('[role="option"]', listbox);
    if (opts[activeIdx]) choose(opts[activeIdx].dataset.id);
    else if (input.value.trim()) startCreate(input.value.trim());
  } else return;
  e.preventDefault();
});

/* ---------- invitation ---------- */
invite.addEventListener('click', (e) => {
  const b = e.target.closest('[data-inv]');
  if (!b || !invitation) return;
  const card = $('.mnv-orgs__inv', invite);
  if (b.dataset.inv === 'no') {
    const name = invitation.n;
    invitation = null;
    if (RM.matches) renderInvite('');
    else card.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'scale(.96)' }], { duration: 220, easing: 'ease-in' }).onfinish = () => renderInvite('');
    say('Declined ' + name);
    input.focus();
    return;
  }
  b.setAttribute('aria-busy', 'true');
  b.textContent = 'Joining…';
  later(600, () => {
    const w = invitation;
    invitation = null;
    const before = new Map($$('[role="option"]', listbox).map((o) => [o.dataset.id, o.getBoundingClientRect().top]));
    WS.splice(WS.length - 1, 0, w);
    renderList();
    if (!RM.matches) {
      $$('[role="option"]', listbox).forEach((o) => {
        const t = before.get(o.dataset.id);
        if (t == null) { o.animate([{ opacity: 0, transform: 'translateY(8px) scale(.98)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.22,1,.36,1)' }); return; }
        const dy = t - o.getBoundingClientRect().top;
        if (dy) o.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.22,1,.36,1)' });
      });
    }
    setActive(shown.indexOf(w));
    input.focus();
    say('Joined ' + w.n + '. Press Enter to switch to it.');
  });
});

/* ---------- create ---------- */
function startCreate(name) {
  createBtn.hidden = true;
  form.hidden = false;
  formInput.value = name || '';
  formInput.focus();
  $('button', form).disabled = !formInput.value.trim();
}
createBtn.addEventListener('click', () => startCreate(input.value.trim()));
formInput.addEventListener('input', () => { $('button', form).disabled = !formInput.value.trim(); });
formInput.addEventListener('keydown', (e) => { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); form.hidden = true; createBtn.hidden = false; input.focus(); } });
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const n = formInput.value.trim();
  if (!n) return;
  const ini = n.split(/\s+/).map((p) => p[0]).join('').slice(0, 2).toUpperCase();
  const h = Math.round((hue + 137.5) % 360 + 360) % 360;
  const w = { id: 'new-' + Date.now(), n, ini, h, role: 'Owner', plan: 'Free', m: 1, seats: 3, inbox: 0, mine: 0, mail: n.toLowerCase().replace(/[^a-z0-9]+/g, '') + '.team', projects: [['Getting started', 0]] };
  WS.splice(WS.length - 1, 0, w);
  form.hidden = true;
  createBtn.hidden = false;
  choose(w.id);
});

/* ---------- nav + shortcuts ---------- */
$('.mnv-orgs__nav').addEventListener('click', (e) => {
  const a = e.target.closest('a');
  if (!a) return;
  e.preventDefault();
  $$('.mnv-orgs__link').forEach((x) => x.removeAttribute('aria-current'));
  a.setAttribute('aria-current', 'page');
});
root.addEventListener('keydown', (e) => {
  const m = /^Digit([1-9])$/.exec(e.code || '');
  if (!e.altKey || e.metaKey || e.ctrlKey || !m) return;
  const w = WS[+m[1] - 1];
  if (!w) return;
  e.preventDefault();
  choose(w.id);
});

paintShell(byId(current));

css:
@property --mnv-toc-t {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}
@property --mnv-toc-b {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

/* Re-theme with --mnv-toc-paper, -ink and -accent. */
.mnv-toc {
  --mnv-toc-paper: oklch(0.985 0.006 95);
  --mnv-toc-ink: oklch(0.22 0.018 255);
  --mnv-toc-accent: oklch(0.47 0.13 250);

  --mnv-toc-line: color-mix(in oklch, var(--mnv-toc-ink) 11%, transparent);
  --mnv-toc-muted: color-mix(in oklch, var(--mnv-toc-ink) 68%, var(--mnv-toc-paper));
  --mnv-toc-faint: color-mix(in oklch, var(--mnv-toc-ink) 40%, var(--mnv-toc-paper));
  --mnv-toc-tick: color-mix(in oklch, var(--mnv-toc-ink) 22%, var(--mnv-toc-paper));
  --mnv-toc-code: color-mix(in oklch, var(--mnv-toc-ink) 5%, var(--mnv-toc-paper));
  --mnv-toc-ring: color-mix(in oklch, var(--mnv-toc-accent) 70%, transparent);
  --mnv-toc-ease: cubic-bezier(.2, .8, .2, 1);
  --mnv-toc-rail: 34px;
  --mnv-toc-panel: min(224px, 74cqi);

  position: relative;
  container-type: inline-size;
  color-scheme: light;
  timeline-scope: --mnv-toc-read;
  box-sizing: border-box;
  width: 100%;
  height: 470px;
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  color: var(--mnv-toc-ink);
  background: var(--mnv-toc-paper);
  box-shadow: 0 0 0 1px var(--mnv-toc-line), 0 22px 44px -30px oklch(0.25 0.04 255 / .5);
  font: 400 13px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
:where(.mnv-toc) *, :where(.mnv-toc) *::before, :where(.mnv-toc) *::after { box-sizing: border-box; }
/* the grid lives one level down: an element cannot query its own container size */
.mnv-toc__frame {
  position: relative; height: 100%;
  display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "bar" "article";
}
:where(.mnv-toc) :focus-visible { outline: 2px solid var(--mnv-toc-ring); outline-offset: 2px; }
.mnv-toc svg { width: 12px; height: 12px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* ---------- top bar ---------- */
.mnv-toc__bar {
  grid-area: bar; position: relative;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  height: 42px; padding: 0 14px;
  font-size: 11.5px; color: var(--mnv-toc-faint); border-bottom: 1px solid var(--mnv-toc-line);
}
.mnv-toc__crumb { display: inline-flex; align-items: center; gap: 4px; font-weight: 550; white-space: nowrap; overflow: hidden; }
.mnv-toc__time { display: inline-flex; gap: 6px; white-space: nowrap; font-variant-numeric: tabular-nums; }
.mnv-toc__pct { font: 600 11px/1.55 ui-monospace, Menlo, monospace; color: var(--mnv-toc-accent); min-width: 4ch; text-align: right; }
.mnv-toc__progress {
  position: absolute; left: 0; right: 0; bottom: -1px; height: 2px;
  & i { position: absolute; inset: 0; background: var(--mnv-toc-accent); transform-origin: 0 50%; transform: scaleX(var(--mnv-toc-p, 0)); }
}
@supports (animation-timeline: scroll()) {
  .mnv-toc__article { scroll-timeline: --mnv-toc-read block; }
  .mnv-toc__progress i { animation: mnv-toc-read linear both; animation-timeline: --mnv-toc-read; }
}

/* ---------- article ---------- */
.mnv-toc__article {
  grid-area: article; position: relative; min-height: 0; overflow: auto; overscroll-behavior: contain;
  padding: 18px calc(var(--mnv-toc-rail) + 14px) 40px 18px; outline: none;
  scrollbar-width: none; /* the tick rail and the progress bar already say where you are */
  &::-webkit-scrollbar { display: none; }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--mnv-toc-ring); }
  & p { margin: 0 0 10px; text-wrap: pretty; color: var(--mnv-toc-muted); }
  & em { font-style: normal; font-weight: 650; color: var(--mnv-toc-ink); }
  & code { font: 500 .88em/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border-radius: 4px; background: var(--mnv-toc-code); color: var(--mnv-toc-ink); }
  & pre { margin: 0 0 12px; padding: 9px 11px; border-radius: 8px; background: var(--mnv-toc-code); overflow: auto; box-shadow: inset 2px 0 0 var(--mnv-toc-line); }
  & pre code { padding: 0; background: none; font-size: 11px; line-height: 1.6; white-space: pre; }
  & section { scroll-margin-top: 10px; }
  & h3, & h4 { outline: none; scroll-margin-top: 12px; text-wrap: balance; }
  & h3 { margin: 26px 0 8px; font-size: 15.5px; font-weight: 720; letter-spacing: -.015em; }
  & h4 { margin: 16px 0 6px; font-size: 13px; font-weight: 680; }
  & :is(h3, h4).is-flash { animation: mnv-toc-flash 1.2s var(--mnv-toc-ease); }
}
.mnv-toc__eyebrow { font-size: 10.5px !important; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--mnv-toc-accent) !important; margin-bottom: 6px !important; }
.mnv-toc__title { margin: 0 0 10px; font-size: clamp(19px, 6.4cqi, 26px); line-height: 1.12; font-weight: 780; letter-spacing: -.03em; text-wrap: balance; }
.mnv-toc__lede { font-size: 13.5px; color: var(--mnv-toc-ink) !important; }
.mnv-toc__end { margin-top: 18px !important; font-size: 11.5px; color: var(--mnv-toc-faint) !important; }

/* ---------- the rail: one panel, clipped down to its tick column ---------- */
.mnv-toc__nav {
  position: absolute; top: 42px; right: 0; bottom: 0; z-index: 3;
  width: var(--mnv-toc-panel);
  padding: 14px 0 14px 14px;
  overflow: hidden;
  background: color-mix(in oklch, var(--mnv-toc-paper) 0%, transparent);
