const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = 'mnv-toc-' + Math.random().toString(36).slice(2, 7);
const article = $('.mnv-toc__article'), nav = $('.mnv-toc__nav'), list = $('.mnv-toc__list');
const bracket = $('.mnv-toc__bracket'), pct = $('.mnv-toc__pct'), bar = $('.mnv-toc__progress i');
const sections = $$('section', article);

/* build the outline from the headings themselves */
const heads = sections.map((s, i) => {
  const h = $('h3, h4', s);
  h.id = UID + '-s' + i;
  h.tabIndex = -1;
  return h;
});
list.innerHTML = heads.map((h, i) =>
  '<li data-lvl="' + (h.tagName === 'H3' ? 1 : 2) + '" style="--i:' + i + '"><a class="mnv-toc__link" href="#' + h.id + '" data-i="' + i + '">' +
  '<span class="mnv-toc__label">' + h.textContent + '</span><span class="mnv-toc__tick" aria-hidden="true"></span></a></li>').join('');
const rows = $$('li', list), links = $$('a', list);

/* ---------- scroll spy, rooted on the article's own scroller ---------- */
const seen = new Set();
function paint() {
  const on = [...seen].sort((a, b) => a - b);
  rows.forEach((r, i) => {
    r.classList.toggle('is-on', seen.has(i));
    r.classList.toggle('is-lead', i === on[0]);
  });
  links.forEach((a, i) => { if (i === on[0]) a.setAttribute('aria-current', 'location'); else a.removeAttribute('aria-current'); });
  if (!on.length) return;
  const first = rows[on[0]], last = rows[on[on.length - 1]];
  const y = list.offsetTop;
  bracket.style.setProperty('--mnv-toc-t', y + first.offsetTop + 5 + 'px');
  bracket.style.setProperty('--mnv-toc-b', y + last.offsetTop + last.offsetHeight - 5 + 'px');
}
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  entries.forEach((e) => {
    const i = sections.indexOf(e.target);
    if (e.isIntersecting) seen.add(i); else seen.delete(i);
  });
  paint();
}, { root: article, rootMargin: '-6px 0px -12% 0px', threshold: 0 });
sections.forEach((s) => io.observe(s));

/* bracket offsets are measured against the list, so re-measure if the panel reflows */
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } paint(); });
ro.observe(list);

/* ---------- reading progress (CSS scroll timeline where supported; the % label always) ---------- */
let ticking = false;
article.addEventListener('scroll', () => {
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(() => {
    if (!root.isConnected) return;
    ticking = false;
    const max = article.scrollHeight - article.clientHeight;
    const p = max > 0 ? Math.min(1, article.scrollTop / max) : 0;
    pct.textContent = Math.round(p * 100) + '%';
    bar.style.setProperty('--mnv-toc-p', p);
  });
}, { passive: true });

/* ---------- jumping ---------- */
function jump(i) {
  const h = heads[i], s = sections[i];
  const top = s.offsetTop - 8;
  article.scrollTo({ top, behavior: RM.matches ? 'auto' : 'smooth' });
  h.focus({ preventScroll: true });
  if (!RM.matches) { h.classList.remove('is-flash'); void h.offsetWidth; h.classList.add('is-flash'); }
}
list.addEventListener('click', (e) => {
  const a = e.target.closest('a[data-i]');
  if (!a) return;
  e.preventDefault();
  jump(+a.dataset.i);
});
list.addEventListener('keydown', (e) => {
  const k = links.indexOf(e.target);
  if (k < 0) return;
  let n = null;
  if (e.key === 'ArrowDown') n = Math.min(links.length - 1, k + 1);
  else if (e.key === 'ArrowUp') n = Math.max(0, k - 1);
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = links.length - 1;
  else if (e.key === 'Escape') { e.preventDefault(); article.focus({ preventScroll: true }); return; }
  else return;
  e.preventDefault();
  links[n].focus();
});
paint();

