/* Re-theme with --mnv-mega-bg, -ink and -accent. */
.mnv-mega {
  --mnv-mega-bg: oklch(0.205 0.018 55);
  --mnv-mega-ink: oklch(0.94 0.018 80);
  --mnv-mega-accent: oklch(0.79 0.12 78);

  --mnv-mega-panel: color-mix(in oklch, var(--mnv-mega-ink) 5%, var(--mnv-mega-bg));
  --mnv-mega-line: color-mix(in oklch, var(--mnv-mega-ink) 10%, transparent);
  --mnv-mega-muted: color-mix(in oklch, var(--mnv-mega-ink) 64%, var(--mnv-mega-bg));
  --mnv-mega-faint: color-mix(in oklch, var(--mnv-mega-ink) 40%, var(--mnv-mega-bg));
  --mnv-mega-hover: color-mix(in oklch, var(--mnv-mega-ink) 6%, transparent);
  --mnv-mega-ring: color-mix(in oklch, var(--mnv-mega-accent) 80%, transparent);
  --mnv-mega-ease: cubic-bezier(.22, 1, .36, 1);
  --mnv-mega-col: clamp(108px, 38cqi, 156px);

  position: relative;
  container-type: inline-size;
  color-scheme: dark;
  box-sizing: border-box;
  width: 100%;
  height: 430px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  overflow: clip;
  border-radius: 16px;
  color: var(--mnv-mega-ink);
  background:
    radial-gradient(80% 60% at 100% 0%, color-mix(in oklch, var(--mnv-mega-accent) 9%, transparent), transparent 70%),
    var(--mnv-mega-bg);
  box-shadow: 0 0 0 1px var(--mnv-mega-line), 0 24px 48px -28px oklch(0 0 0 / .8);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
  accent-color: var(--mnv-mega-accent);
}
:where(.mnv-mega) *, :where(.mnv-mega) *::before, :where(.mnv-mega) *::after { box-sizing: border-box; }
:where(.mnv-mega) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnv-mega) :focus-visible { outline: 2px solid var(--mnv-mega-ring); outline-offset: 2px; }
.mnv-mega svg { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.mnv-mega__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- top bar ---------- */
