  display: grid; grid-template-columns: auto auto minmax(0, 1fr); align-items: center; gap: 10px;
  height: 52px; padding: 0 12px 0 14px; border-bottom: 1px solid var(--mnv-mega-line);
}
.mnv-mega__brand {
  display: inline-flex; align-items: center; gap: 7px; font-weight: 760; letter-spacing: -.02em; font-size: 14.5px;
  & svg { width: 20px; height: 20px; color: var(--mnv-mega-accent); }
}
