  display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 11px 0 9px; border-radius: 9px;
  font-weight: 650; font-size: 12.5px; color: var(--mnv-mega-muted); box-shadow: inset 0 0 0 1px var(--mnv-mega-line);
  transition: background-color .2s, color .2s;
