  & b { position: absolute; top: 1px; right: -1px; min-width: 15px; height: 15px; padding: 0 3px; border-radius: 8px; display: grid; place-items: center; font: 750 9.5px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: oklch(0.22 0.04 70); background: var(--mnv-mega-accent); }
}

/* ---------- the "page" behind the menu ---------- */
