  grid-area: 2 / 1; padding: 16px 16px 0; min-width: 0;
  & p { margin: 0; }
}
.mnv-mega__crumb { font-size: 11px; color: var(--mnv-mega-faint); font-weight: 550; }
.mnv-mega__ph { margin: 4px 0 2px; font-size: clamp(17px, 6cqi, 21px); font-weight: 740; letter-spacing: -.025em; text-wrap: balance; }
.mnv-mega__pc { font-size: 12px; color: var(--mnv-mega-muted); font-variant-numeric: tabular-nums; }
.mnv-mega__gl { margin: 18px 0 8px !important; font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mnv-mega-faint); }
