    color: var(--mnv-mega-muted); box-shadow: inset 0 0 0 1px var(--mnv-mega-line); transition: background-color .2s, color .2s;
  }
  & button:hover { color: var(--mnv-mega-ink); background: var(--mnv-mega-hover); }
  & em { font-style: normal; font-size: 11px; color: var(--mnv-mega-faint); font-variant-numeric: tabular-nums; }
  & button[aria-pressed="true"] { color: oklch(0.22 0.04 70); background: var(--mnv-mega-accent); box-shadow: none; & em { color: oklch(0.3 0.05 70); } }
}
.mnv-mega__note {
  display: flex; align-items: center; gap: 8px; margin-top: 16px !important; padding: 10px 12px; border-radius: 10px;
  font-size: 12px; color: var(--mnv-mega-muted); background: var(--mnv-mega-hover); text-wrap: pretty;
  & svg { color: var(--mnv-mega-accent); }
}

/* ---------- menu ---------- */
.mnv-mega__menu {
  grid-area: 2 / 1; position: relative; z-index: 2; min-height: 0;
  display: grid; grid-template-columns: var(--mnv-mega-col) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto;
  background: var(--mnv-mega-bg);
  clip-path: inset(0 0 0 0);
  transition: clip-path .38s var(--mnv-mega-ease), opacity .25s, visibility 0s;
  &.is-closed { clip-path: inset(0 0 100% 0); opacity: 0; visibility: hidden; transition: clip-path .3s var(--mnv-mega-ease), opacity .25s, visibility 0s .3s; }
}
