  position: relative; grid-row: 1 / -1; padding: 8px 6px; overflow: auto; scrollbar-width: none;
  border-right: 1px solid var(--mnv-mega-line);
  & ul { list-style: none; margin: 0; padding: 0; position: relative; display: grid; gap: 1px; }
}
.mnv-mega__lens {
  position: absolute; left: 6px; right: 6px; top: 8px; height: 34px; border-radius: 9px; z-index: 0;
  background: color-mix(in oklch, var(--mnv-mega-accent) 15%, transparent);
  box-shadow: inset 2px 0 0 var(--mnv-mega-accent);
  transform: translateY(var(--y, 0px));
  transition: transform .32s var(--mnv-mega-ease), opacity .2s;
}
.mnv-mega__dept {
  position: relative; z-index: 1; width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px;
  height: 34px; padding: 0 4px 0 9px; border-radius: 9px; text-align: left; outline: none; column-gap: 7px;
  color: var(--mnv-mega-muted); font-size: 12.5px; font-weight: 550;
  transition: color .2s;
  & svg { width: 16px; height: 16px; }
  & span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .mnv-mega__chev { width: 12px; height: 12px; opacity: 0; translate: -3px 0; transition: opacity .2s, translate .25s var(--mnv-mega-ease); }
