  &[aria-expanded="true"] { color: var(--mnv-mega-ink); font-weight: 650; & .mnv-mega__chev { opacity: 1; translate: 0 0; color: var(--mnv-mega-accent); } }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--mnv-mega-ring); }
  &[aria-disabled="true"] { color: var(--mnv-mega-faint); }
  &.is-sale { color: var(--mnv-mega-accent); }
}
.mnv-mega__panel {
  position: relative; min-width: 0; min-height: 0; overflow: auto; padding: 12px 14px 8px; scrollbar-width: none;
  &.is-swap > * { animation: mnv-mega-in .34s var(--mnv-mega-ease) both; animation-delay: calc(var(--i, 0) * 40ms); }
}
.mnv-mega__ptitle { margin: 0 0 8px; font-size: 14px; font-weight: 720; letter-spacing: -.015em; display: flex; align-items: baseline; gap: 8px; justify-content: space-between; & small { font-size: 11px; font-weight: 500; color: var(--mnv-mega-faint); font-variant-numeric: tabular-nums; white-space: nowrap; } }
.mnv-mega__group { margin-bottom: 10px; }
.mnv-mega__gh { margin: 0 0 3px; font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--mnv-mega-faint); }
.mnv-mega__link {
  display: flex; justify-content: space-between; align-items: center; gap: 8px; height: 28px; padding: 0 8px; margin: 0 -8px; width: calc(100% + 16px);
  border-radius: 7px; font-size: 12.5px; color: var(--mnv-mega-ink); text-align: left; outline: none;
  & em { font-style: normal; font-size: 11px; color: var(--mnv-mega-faint); font-variant-numeric: tabular-nums; }
