}
.mnv-mega__promo {
  display: grid; gap: 2px; margin-top: 4px; padding: 10px 11px; border-radius: 10px;
  background: color-mix(in oklch, var(--mnv-mega-accent) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mnv-mega-accent) 28%, transparent);
  & b { font-size: 12.5px; font-weight: 700; color: var(--mnv-mega-accent); text-wrap: balance; }
  & span { font-size: 11.5px; color: var(--mnv-mega-muted); text-wrap: pretty; }
}
.mnv-mega__soon {
  display: grid; justify-items: start; gap: 6px; padding-top: 6px;
  & svg { width: 34px; height: 34px; stroke-width: 1.4; color: var(--mnv-mega-faint); }
  & p { margin: 0; font-size: 12.5px; color: var(--mnv-mega-muted); text-wrap: pretty; }
  & b { color: var(--mnv-mega-ink); }
  & button { margin-top: 4px; padding: 7px 11px; border-radius: 8px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--mnv-mega-line); }
  & button { width: auto; margin: 4px 0 0; justify-content: center; }
