  opacity: 0; transition: opacity .2s;
  & polygon { fill: color-mix(in oklch, var(--mnv-mega-accent) 7%, transparent); stroke: color-mix(in oklch, var(--mnv-mega-accent) 45%, transparent); stroke-width: 1; stroke-dasharray: 3 3; transition: fill .15s; }
  & circle { fill: var(--mnv-mega-accent); stroke: none; }
  &.is-holding polygon { fill: color-mix(in oklch, var(--mnv-mega-accent) 22%, transparent); stroke: var(--mnv-mega-accent); }
}
.mnv-mega__menu:has(.mnv-mega__debug input:checked) .mnv-mega__aim.is-live { opacity: 1; }
.mnv-mega__debug {
  grid-column: 2; display: flex; align-items: center; gap: 8px; padding: 8px 14px 10px; font-size: 11.5px; color: var(--mnv-mega-faint); cursor: pointer;
  border-top: 1px solid var(--mnv-mega-line);
  & input {
    appearance: none; margin: 0; width: 28px; height: 16px; border-radius: 8px; position: relative; cursor: pointer;
    background: var(--mnv-mega-line); transition: background-color .2s;
    &::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--mnv-mega-ink); transition: translate .25s var(--mnv-mega-ease); }
    &:checked { background: var(--mnv-mega-accent); &::after { translate: 12px 0; background: oklch(0.22 0.04 70); } }
  }
}

@container (max-width: 300px) {
  .mnv-mega__brand { font-size: 0; gap: 0; }
  .mnv-mega__dept svg:first-child { display: none; }
  .mnv-mega__dept { grid-template-columns: minmax(0, 1fr) auto; }
}

@keyframes mnv-mega-in { from { opacity: 0; translate: 6px 0; } }

@media (prefers-reduced-motion: reduce) {
  .mnv-mega__lens, .mnv-mega__menu, .mnv-mega__menu.is-closed { transition: none; }
