const CHEV = '<svg class="mnv-mega__chev" viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 6.5 5.5 5.5-5.5 5.5"/></svg>';
const fmt = (n) => n.toLocaleString('en-GB');

const D = [
  { n: 'Tools', i: '<path d="M14.5 5.5a4 4 0 0 0 4.9 4.9L12 17.8a2.1 2.1 0 0 1-3-3l7.4-7.4"/><path d="M5 19l2.5-2.5"/>',
    g: [['Power tools', [['Drills & drivers', 214], ['Saws', 96], ['Sanders', 41]]], ['Hand tools', [['Hammers', 58], ['Spanners & sockets', 133], ['Measuring', 77]]]],
    promo: ['Cordless drill kits from £69', 'Two batteries and a case in every kit.'] },
  { n: 'Garden', i: '<path d="M12 20v-7"/><path d="M12 13c-3.6 0-6-2.5-6-6.5 3.8 0 6 2.6 6 6.5Z"/><path d="M12 13c0-3.9 2.3-6.5 6-6.5 0 4-2.4 6.5-6 6.5Z"/><path d="M7 20h10"/>',
    g: [['Growing', [['Seeds & bulbs', 320], ['Compost & soil', 48], ['Planters', 112]]], ['Lawn', [['Mowers', 36], ['Trimmers', 22], ['Lawn feed', 19]]]],
    promo: ['Autumn bulbs: 3 for 2', 'Tulips, alliums and crocus until 31 October.'] },
  { n: 'Lighting', i: '<path d="M9 17.5h6M10 20.5h4"/><path d="M12 3.5a5.5 5.5 0 0 0-3.2 10c.5.4.7 1 .7 1.6v.4h5v-.4c0-.6.2-1.2.7-1.6A5.5 5.5 0 0 0 12 3.5Z"/>',
    g: [['Indoor', [['Pendants', 88], ['Floor lamps', 41], ['Bulbs', 230]]], ['Outdoor', [['Wall lights', 52], ['Solar', 64], ['Floodlights', 18]]]],
    promo: ['Warm-white LED swap', 'Trade in five old bulbs, take 20% off new ones.'] },
  { n: 'Paint', i: '<path d="M4.5 5.5h12v5h-12Z"/><path d="M16.5 8h3v5.5H11V16"/><path d="M10 16h2v4.5h-2Z"/>',
    g: [['Interior', [['Emulsion', 140], ['Primers', 33], ['Wood stain', 57]]], ['Prep & tools', [['Brushes', 75], ['Rollers', 46], ['Masking', 21]]]],
    promo: ['Colour matched while you wait', 'Bring a chip of anything; most mixes take 10 minutes.'] },
  { n: 'Storage', i: '<path d="M4.5 8h15v11.5h-15Z"/><path d="M3.5 4.5h17V8h-17ZM10 11.5h4"/>',
    g: [['Home', [['Shelving', 63], ['Boxes & bins', 154], ['Hooks & rails', 47]]], ['Garage', [['Wall racks', 37], ['Tool chests', 29], ['Workbenches', 15]]]],
    promo: ['Free wall-mounting kit', 'With any garage rack over £120.'] },
  { n: 'Plumbing', i: '<path d="M4.5 10.5h9a3.5 3.5 0 0 1 3.5 3.5v1.5"/><path d="M4.5 8v5M9.5 10.5V7M7 7h5M17 19v.5"/>', soon: '14 November', count: 1240 },
  { n: 'Clearance', i: '<path d="M11.5 4.5h7v7l-8.6 8.6a1.4 1.4 0 0 1-2 0L3 15.2a1.4 1.4 0 0 1 0-2Z"/><circle cx="15" cy="8" r="1.2"/>', sale: true,
    g: [['Ending soon', [['Garden furniture', 27], ['Heaters', 14], ['Christmas lights', 31]]], ['Last few', [['Ex-display tools', 9], ['Paint mis-tints', 62], ['Odd tiles', 18]]]],
    promo: ['Up to 40% off', 'Prices drop every Monday until it is gone.'] },
];
let active = 1, open = true, notify = false;
let page = { d: 1, g: 0, cat: 'Seeds & bulbs', n: 320 };

ul.innerHTML = D.map((d, k) =>
  '<li role="none"><button type="button" role="menuitem" class="mnv-mega__dept' + (d.sale ? ' is-sale' : '') + '" id="' + UID + '-d' + k + '" data-k="' + k + '" aria-haspopup="menu" aria-expanded="false" tabindex="-1"' +
  (d.soon ? ' aria-disabled="true"' : '') + '>' + svg(d.i) + '<span>' + esc(d.n) + '</span>' + CHEV + '</button></li>').join('');
const depts = $$('.mnv-mega__dept');
panel.id = UID + '-panel';

function paintPage() {
  const grp = D[page.d].g[page.g];
  $('.mnv-mega__crumb').textContent = 'Home / ' + D[page.d].n + ' / ' + grp[0];
  $('.mnv-mega__ph').textContent = page.cat;
  $('.mnv-mega__pc').textContent = fmt(page.n) + ' products · Free click and collect';
  $('.mnv-mega__gl').textContent = 'More in ' + grp[0];
  const chips = $('.mnv-mega__chips');
  chips.setAttribute('aria-label', 'More in ' + grp[0]);
  chips.innerHTML = grp[1].map((l) => '<button type="button" data-cat="' + esc(l[0]) + '" data-n="' + l[1] + '" aria-pressed="' + (l[0] === page.cat) + '">' + esc(l[0]) + '<em>' + fmt(l[1]) + '</em></button>').join('');
}
$('.mnv-mega__chips').addEventListener('click', (e) => {
  const b = e.target.closest('[data-cat]');
  if (!b || b.getAttribute('aria-pressed') === 'true') return;
  page.cat = b.dataset.cat;
  page.n = +b.dataset.n;
  paintPage();
  $('[data-cat="' + CSS.escape(page.cat) + '"]', $('.mnv-mega__chips')).focus();
});

/* ---------- activate a department ---------- */
function activate(k, swap) {
  if (k === active && panel.childElementCount && !swap) return;
  active = k;
  const d = D[k];
  depts.forEach((b, i) => {
    b.setAttribute('aria-expanded', String(i === k));
    if (i === k) b.setAttribute('aria-controls', panel.id); else b.removeAttribute('aria-controls');
  });
  panel.setAttribute('aria-labelledby', depts[k].id);
  lens.style.setProperty('--y', depts[k].offsetTop + 'px');
  if (d.soon) {
    panel.innerHTML = '<div class="mnv-mega__soon" style="--i:0">' + svg('<rect x="4.5" y="5.5" width="15" height="14" rx="2"/><path d="M4.5 9.5h15M9 3.5v4M15 3.5v4"/>') +
      '<p><b>' + esc(d.n) + ' opens on ' + d.soon + '.</b> ' + fmt(d.count) + ' products are on their way, from basin wrenches to whole-house filters.</p>' +
      '<button type="button" role="menuitemcheckbox" tabindex="-1" class="mnv-mega__link" data-notify aria-checked="' + notify + '">' + (notify ? 'We will email you' : 'Email me when it opens') + '</button></div>';
  } else {
    const total = d.g.reduce((a, g) => a + g[1].reduce((b, l) => b + l[1], 0), 0);
    panel.innerHTML = '<p class="mnv-mega__ptitle" style="--i:0">' + esc(d.n) + '<small>' + fmt(total) + ' products</small></p>' +
      d.g.map((g, gi) => '<div class="mnv-mega__group" role="group" aria-label="' + esc(g[0]) + '" style="--i:' + (gi + 1) + '"><p class="mnv-mega__gh" aria-hidden="true">' + esc(g[0]) + '</p>' +
        g[1].map((l) => '<button type="button" role="menuitem" tabindex="-1" class="mnv-mega__link" data-cat="' + esc(l[0]) + '" data-n="' + l[1] + '"><span>' + esc(l[0]) + '</span><em>' + fmt(l[1]) + '</em></button>').join('') + '</div>').join('') +
      '<p class="mnv-mega__promo" style="--i:3"><b>' + esc(d.promo[0]) + '</b><span>' + esc(d.promo[1]) + '</span></p>';
  }
  if (!RM.matches) { panel.classList.remove('is-swap'); void panel.offsetWidth; panel.classList.add('is-swap'); }
}

/* ---------- menu-aim ---------- */
const trail = [];
let holdTimer = 0, holdAt = null, pending = -1;
function corners() {
  const p = panel.getBoundingClientRect();
  return { up: { x: p.left, y: p.top - 24 }, low: { x: p.left, y: p.bottom + 24 } };
}
function heading() {
  const cur = trail[trail.length - 1], prev = trail[0];
  if (!cur || !prev || cur === prev) return false;
  if (holdAt && cur.x === holdAt.x && cur.y === holdAt.y) return false;
  const { up, low } = corners();
  const slope = (a, b) => (b.y - a.y) / ((b.x - a.x) || 0.0001);
  /* moving inside the triangle: the slope to the top corner falls and the slope to the bottom corner rises */
  return slope(cur, up) < slope(prev, up) && slope(cur, low) > slope(prev, low);
}
function drawAim(holding) {
  const cur = trail[trail.length - 1];
  if (!cur) return;
  const r = menu.getBoundingClientRect(), { up, low } = corners();
  const pt = (p) => (p.x - r.left).toFixed(1) + ',' + (p.y - r.top).toFixed(1);
  poly.setAttribute('points', pt(cur) + ' ' + pt(up) + ' ' + pt(low));
  dot.setAttribute('cx', (cur.x - r.left).toFixed(1));
  dot.setAttribute('cy', (cur.y - r.top).toFixed(1));
  aim.classList.toggle('is-holding', !!holding);
}
function offer(k) {
  clearTimeout(holdTimer);
  if (k === active) { holdAt = null; return false; }
  if (heading()) {
    holdAt = trail[trail.length - 1];
    pending = k;
    holdTimer = setTimeout(() => { if (!root.isConnected) return; drawAim(offer(pending)); }, 280);
    return true;
  }
  holdAt = null;
  activate(k);
  return false;
}
const deptsBox = $('.mnv-mega__depts');
deptsBox.addEventListener('pointermove', (e) => {
  if (e.pointerType !== 'mouse') return;
  trail.push({ x: e.clientX, y: e.clientY });
  if (trail.length > 3) trail.shift();
  aim.classList.add('is-live');
  const b = e.target.closest('.mnv-mega__dept');
  drawAim(b ? offer(+b.dataset.k) : false);
});
deptsBox.addEventListener('pointerleave', () => { aim.classList.remove('is-live'); });
panel.addEventListener('pointerenter', () => { clearTimeout(holdTimer); aim.classList.remove('is-live'); });

/* ---------- open / close / choose ---------- */
function setOpen(v, focusDept) {
  open = v;
  menu.classList.toggle('is-closed', !v);
  menu.inert = !v;
  trigger.setAttribute('aria-expanded', String(v));
  if (v) {
    activate(active, true);
    if (focusDept) focusItem(depts[active]);
  }
}
function focusItem(b) {
  depts.forEach((x) => { x.tabIndex = x === b ? 0 : -1; });
  b.focus();
}
function choose(link) {
  const g = D[active].g.findIndex((grp) => grp[1].some((l) => l[0] === link.dataset.cat));
  page = { d: active, g: Math.max(0, g), cat: link.dataset.cat, n: +link.dataset.n };
  paintPage();
  setOpen(false);
  trigger.focus();
  say(page.cat + ', ' + fmt(page.n) + ' products');
}
trigger.addEventListener('click', () => setOpen(!open, !open));
trigger.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown') { e.preventDefault(); setOpen(true, true); }
});
ul.addEventListener('click', (e) => {
  const b = e.target.closest('.mnv-mega__dept');
  if (!b) return;
  clearTimeout(holdTimer);
  activate(+b.dataset.k);
  focusItem(b);
});
panel.addEventListener('click', (e) => {
  const n = e.target.closest('[data-notify]');
  if (n) {
    notify = !notify;
    n.setAttribute('aria-checked', String(notify));
    n.textContent = notify ? 'We will email you' : 'Email me when it opens';
    say(notify ? 'We will email you when Plumbing opens' : 'Reminder cancelled');
    return;
  }
  const l = e.target.closest('[data-cat]');
  if (l) choose(l);
});

ul.addEventListener('keydown', (e) => {
  const k = depts.indexOf(e.target);
  if (k < 0) return;
  let n = null;
  if (e.key === 'ArrowDown') n = (k + 1) % depts.length;
  else if (e.key === 'ArrowUp') n = (k - 1 + depts.length) % depts.length;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = depts.length - 1;
  else if (e.key === 'ArrowRight' || e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    activate(k);
    const first = $('[role^="menuitem"]', panel);
    if (first) { first.tabIndex = 0; first.focus(); }
    return;
  } else if (e.key === 'Escape') { e.preventDefault(); setOpen(false); trigger.focus(); return; }
  else if (e.key.length === 1 && /\S/.test(e.key)) {
    const order = depts.slice(k + 1).concat(depts.slice(0, k + 1));
    const hit = order.find((b) => b.textContent.trim().toLowerCase().startsWith(e.key.toLowerCase()));
    if (hit) n = depts.indexOf(hit); else return;
  } else return;
  e.preventDefault();
  activate(n);
  focusItem(depts[n]);
});
panel.addEventListener('keydown', (e) => {
  const items = $$('[role^="menuitem"]', panel), k = items.indexOf(e.target);
  if (k < 0) return;
  let n = null;
  if (e.key === 'ArrowDown') n = (k + 1) % items.length;
  else if (e.key === 'ArrowUp') n = (k - 1 + items.length) % items.length;
  else if (e.key === 'Home') n = 0;
  else if (e.key === 'End') n = items.length - 1;
  else if (e.key === 'ArrowLeft' || e.key === 'Escape') { e.preventDefault(); focusItem(depts[active]); return; }
  else return;
  e.preventDefault();
  items.forEach((x) => { x.tabIndex = -1; });
  items[n].tabIndex = 0;
  items[n].focus();
});

paintPage();
depts[active].tabIndex = 0;
activate(active, true);

