/* Re-theme with --mnv-path-paper, -ink and -accent. */
.mnv-path {
  --mnv-path-paper: oklch(0.977 0.004 250);
  --mnv-path-ink: oklch(0.23 0.02 265);
  --mnv-path-accent: oklch(0.58 0.2 0);
  --mnv-path-ok: oklch(0.66 0.15 150);
  --mnv-path-warn: oklch(0.74 0.15 70);
  --mnv-path-busy: oklch(0.66 0.1 250);

  --mnv-path-card: color-mix(in oklch, white 75%, var(--mnv-path-paper));
  --mnv-path-line: color-mix(in oklch, var(--mnv-path-ink) 11%, transparent);
  --mnv-path-muted: color-mix(in oklch, var(--mnv-path-ink) 64%, var(--mnv-path-paper));
  --mnv-path-faint: color-mix(in oklch, var(--mnv-path-ink) 40%, var(--mnv-path-paper));
  --mnv-path-hover: color-mix(in oklch, var(--mnv-path-ink) 5.5%, transparent);
  --mnv-path-tint: color-mix(in oklch, var(--mnv-path-accent) 10%, var(--mnv-path-card));
  --mnv-path-ring: color-mix(in oklch, var(--mnv-path-accent) 70%, transparent);
  --mnv-path-ease: cubic-bezier(.22, 1, .36, 1);

  position: relative;
  container-type: inline-size;
  color-scheme: light;
  box-sizing: border-box;
  width: 100%;
  min-height: 330px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  overflow: clip;
  border-radius: 14px;
  color: var(--mnv-path-ink);
  background: var(--mnv-path-paper);
  box-shadow: 0 0 0 1px var(--mnv-path-line), 0 22px 44px -30px oklch(0.3 0.04 265 / .5);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-align: left;
}
:where(.mnv-path) *, :where(.mnv-path) *::before, :where(.mnv-path) *::after { box-sizing: border-box; }
:where(.mnv-path) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
:where(.mnv-path) :focus-visible { outline: 2px solid var(--mnv-path-ring); outline-offset: 2px; }
.mnv-path svg { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.mnv-path__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- the trail ---------- */
.mnv-path__trail {
  padding: 10px 10px 9px; border-bottom: 1px solid var(--mnv-path-line);
  background: color-mix(in oklch, white 55%, var(--mnv-path-paper));
  & ol { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; min-width: 0; }
  & li { display: flex; align-items: center; min-width: 0; flex: 0 1 auto; }
  & li:last-child { flex-shrink: 0; max-width: 60%; }
  & li + li::before {
    content: ""; flex: none; width: 12px; height: 18px; margin: 0 1px;
    background: linear-gradient(to top right, transparent calc(50% - .6px), var(--mnv-path-faint) calc(50% - .6px) calc(50% + .6px), transparent calc(50% + .6px));
    opacity: .55;
  }
}
.mnv-path__seg {
  display: inline-flex; align-items: center; gap: 6px; min-width: 0; max-width: 100%;
  height: 30px; padding: 0 5px 0 6px; border-radius: 8px; color: var(--mnv-path-muted); font-weight: 550; font-size: 12.5px;
  transition: background-color .18s, color .18s;
  &:hover, &[aria-expanded="true"] { background: var(--mnv-path-hover); color: var(--mnv-path-ink); }
  &[aria-current="page"] { color: var(--mnv-path-ink); font-weight: 680; }
  & .mnv-path__caret { width: 12px; height: 12px; color: var(--mnv-path-faint); transition: rotate .3s var(--mnv-path-ease); }
  &[aria-expanded="true"] .mnv-path__caret { rotate: 180deg; }
}
.mnv-path__slot { position: relative; display: block; min-width: 0; overflow: hidden; height: 1.4em; line-height: 1.4em; }
.mnv-path__txt { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mnv-path__ghost { position: absolute; left: 0; top: 0; white-space: nowrap; pointer-events: none; }
.mnv-path__tile {
  display: grid; place-items: center; width: 20px; height: 20px; border-radius: 6px; flex: none;
  font: 750 9px/1 system-ui, sans-serif; color: white; background: linear-gradient(140deg, oklch(0.66 0.17 var(--h)), oklch(0.52 0.18 calc(var(--h) + 30)));
}
.mnv-path__dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--c, var(--mnv-path-ok)); box-shadow: 0 0 0 2.5px color-mix(in oklch, var(--c, var(--mnv-path-ok)) 22%, transparent); }
.mnv-path__ico { color: var(--mnv-path-faint); }

/* ---------- sibling switcher ---------- */
.mnv-path__pop {
  position: absolute; top: var(--y, 46px); left: var(--x, 10px); z-index: 4; width: min(244px, calc(100% - 16px));
  display: grid; padding: 6px; border-radius: 12px; background: var(--mnv-path-card);
  box-shadow: 0 0 0 1px var(--mnv-path-line), 0 18px 36px -10px oklch(0.3 0.04 265 / .35);
  transform-origin: 24px 0;
  transition: opacity .16s, scale .24s var(--mnv-path-ease), translate .24s var(--mnv-path-ease), display .24s allow-discrete;
  @starting-style { opacity: 0; scale: .96; translate: 0 -4px; }
  &[hidden] { display: none; opacity: 0; scale: .98; }
}
.mnv-path__ph { margin: 4px 8px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--mnv-path-faint); }
.mnv-path__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; max-height: 214px; overflow: auto; outline: none; scrollbar-width: thin; }
.mnv-path__list:focus-visible { box-shadow: inset 0 0 0 1px var(--mnv-path-ring); border-radius: 8px; }
.mnv-path__opt {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 9px;
  min-height: 36px; padding: 5px 8px; border-radius: 8px; cursor: pointer;
  transition: background-color .12s;
  & b { display: block; font-size: 12.5px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { display: block; font-size: 11px; color: var(--mnv-path-faint); font-variant-numeric: tabular-nums; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .mnv-path__tick { color: var(--mnv-path-accent); opacity: 0; }
  &[aria-selected="true"] { & .mnv-path__tick { opacity: 1; } & b { color: var(--mnv-path-accent); } }
  &.is-active { background: var(--mnv-path-hover); }
  &[aria-disabled="true"] { cursor: not-allowed; & b { color: var(--mnv-path-faint); } }
  &.is-nope { animation: mnv-path-nope .38s var(--mnv-path-ease); }
  transition: background-color .12s, opacity .25s, translate .3s var(--mnv-path-ease);
  transition-delay: 0s, calc(var(--i) * 22ms), calc(var(--i) * 22ms);
  @starting-style { opacity: 0; translate: 0 -3px; }
}
.mnv-path__spin { width: 12px; height: 12px; border-radius: 50%; border: 1.75px solid color-mix(in oklch, var(--mnv-path-busy) 30%, transparent); border-top-color: var(--mnv-path-busy); animation: mnv-path-spin .8s linear infinite; }
.mnv-path__keys {
  display: flex; gap: 12px; margin: 4px 0 0; padding: 8px 8px 3px; border-top: 1px solid var(--mnv-path-line);
  font-size: 11px; color: var(--mnv-path-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--mnv-path-muted); box-shadow: inset 0 0 0 1px var(--mnv-path-line), inset 0 -1px 0 var(--mnv-path-line); }
}

/* ---------- body ---------- */
.mnv-path__body {
  padding: 16px 16px 14px; display: grid; align-content: start; gap: 10px; min-width: 0;
  transition: opacity .2s;
  &[aria-busy="true"] { opacity: .45; }
  &.is-swap > * { animation: mnv-path-in .45s var(--mnv-path-ease) both; animation-delay: calc(var(--i, 0) * 50ms); }
  & p { margin: 0; }
}
.mnv-path__head { display: flex; align-items: center; gap: 8px; min-width: 0; }
.mnv-path__title { margin: 0 0 0 -6px; min-width: 0; font: 700 clamp(16px, 5.4cqi, 20px)/1.15 ui-monospace, Menlo, monospace; letter-spacing: -.03em; }
.mnv-path__tbtn {
  height: auto; padding: 2px 4px 2px 6px; font: inherit; letter-spacing: inherit; color: var(--mnv-path-ink);
  & .mnv-path__caret { width: 16px; height: 16px; }
}
.mnv-path__env {
  flex: none; display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px 3px 7px; border-radius: 999px;
  font-size: 11px; font-weight: 650; color: color-mix(in oklch, var(--c) 62%, black);
  background: color-mix(in oklch, var(--c) 14%, var(--mnv-path-card));
}
.mnv-path__deploy { font-size: 12px; color: var(--mnv-path-muted); text-wrap: pretty; & code { font: 500 11.5px/1 ui-monospace, Menlo, monospace; color: var(--mnv-path-ink); } }
.mnv-path__stats {
  margin: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px; border-radius: 11px; overflow: hidden;
  background: var(--mnv-path-line); box-shadow: 0 0 0 1px var(--mnv-path-line);
  & div { padding: 9px 10px; background: var(--mnv-path-card); min-width: 0; }
  & dt { font-size: 10.5px; font-weight: 600; color: var(--mnv-path-faint); white-space: nowrap; }
  & dd { margin: 2px 0 0; font-size: 15px; font-weight: 720; letter-spacing: -.02em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { font-size: 11px; font-weight: 500; color: var(--mnv-path-faint); letter-spacing: 0; }
  & dd.is-warn { color: color-mix(in oklch, var(--mnv-path-warn) 70%, black); }
}
.mnv-path__chart {
  position: relative; margin: 0; padding: 10px 12px 8px; border-radius: 11px; background: var(--mnv-path-card); box-shadow: 0 0 0 1px var(--mnv-path-line);
  & figcaption { font-size: 10.5px; font-weight: 600; color: var(--mnv-path-faint); margin-bottom: 6px; }
  & svg { display: block; width: 100%; height: 56px; overflow: visible; }
}
.mnv-path__line { fill: none; stroke: var(--mnv-path-accent); stroke-width: 1.75; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
.mnv-path__area { fill: color-mix(in oklch, var(--mnv-path-accent) 12%, transparent); stroke: none; }
.mnv-path__now {
  position: absolute; right: 12px; top: 8px; font: 650 10.5px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  color: var(--mnv-path-accent);
}

@container (max-width: 380px) {
  .mnv-path__seg[data-level="0"] .mnv-path__slot { display: none; }
  .mnv-path__long { display: none; }
}
@container (min-width: 381px) {
  .mnv-path__short { display: none; }
}
@container (max-width: 310px) {
  .mnv-path__seg[data-level="1"] .mnv-path__ico { display: none; }
  .mnv-path__stats dd { font-size: 13.5px; }
}

@keyframes mnv-path-spin { to { rotate: 360deg; } }
@keyframes mnv-path-in { from { opacity: 0; translate: 0 6px; } }
@keyframes mnv-path-nope { 20% { translate: -4px 0; } 45% { translate: 3px 0; } 70% { translate: -2px 0; } }

@media (prefers-reduced-motion: reduce) {
  .mnv-path__pop, .mnv-path__opt { transition: none; }
  .mnv-path__body.is-swap > *, .mnv-path__opt.is-nope { animation: none; }
  .mnv-path__spin { animation-duration: 2.4s; }
}

js:
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const UID = 'mnv-path-' + Math.random().toString(36).slice(2, 7);
const later = (ms, fn) => setTimeout(() => { if (root.isConnected) fn(); }, ms);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const live = $('.mnv-path__sr');
const say = (t) => { live.textContent = ''; later(30, () => { live.textContent = t; }); };
const ol = $('.mnv-path__trail ol'), pop = $('.mnv-path__pop'), listbox = $('.mnv-path__list'), body = $('.mnv-path__body');
const CARET = '<svg class="mnv-path__caret" viewBox="0 0 24 24" aria-hidden="true"><path d="m8 10 4 4 4-4"/></svg>';
const TICK = '<svg class="mnv-path__tick" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg>';
const BOX = '<svg class="mnv-path__ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5 4.5 7.5v9L12 20.5l7.5-4v-9Z"/><path d="m4.5 7.5 7.5 4 7.5-4M12 11.5v9"/></svg>';
const COG = '<svg class="mnv-path__ico" viewBox="0 0 24 24" aria-hidden="true"><rect x="4.5" y="4.5" width="15" height="15" rx="3"/><path d="M8.5 9.5h7M8.5 14.5h4"/></svg>';
const fmt = (n) => Math.round(n).toLocaleString('en-GB');

/* ---------- the world this trail navigates ---------- */
const ORGS = [
  { id: 'pemberton', n: 'Pemberton Labs', ini: 'PL', h: 0, sub: 'Team · 38 members' },
  { id: 'larkhill', n: 'Larkhill Health', ini: 'LH', h: 160, sub: 'Enterprise · 212 members' },
];
const PROJECTS = {
  pemberton: [['checkout-api', 'Node · 4 services'], ['ledger-sync', 'Go · 2 services'], ['search-gateway', 'Rust · 3 services'], ['partner-portal', 'Next · 2 services'], ['mobile-bff', 'Kotlin · 2 services'], ['notifications', 'Go · 3 services']],
  larkhill: [['patient-intake', 'Node · 3 services'], ['records-api', 'Java · 4 services'], ['scheduling', 'Go · 2 services']],
};
const SERVICES = {
  'checkout-api': ['payments-worker', 'cart-service', 'tax-quoter', 'receipt-mailer'], 'ledger-sync': ['reconciler', 'ingest'],
  'search-gateway': ['query-router', 'indexer', 'synonyms'], 'partner-portal': ['web', 'auth-proxy'], 'mobile-bff': ['graph', 'push-relay'],
  'notifications': ['fanout', 'templates', 'digest'], 'patient-intake': ['forms', 'triage', 'uploads'], 'records-api': ['records', 'audit', 'consent', 'export'],
  'scheduling': ['slots', 'reminders'],
};
const ENVS = [
  { id: 'production', short: 'prod', st: 'ok', note: 'Healthy · 6 regions' },
  { id: 'staging', short: 'stage', st: 'warn', note: 'Degraded · 1 of 3 pods restarting' },
  { id: 'preview-pr-482', short: 'pr-482', st: 'busy', note: 'Building · step 4 of 7' },
  { id: 'development', short: 'dev', st: 'ok', note: 'Healthy · 1 region' },
];
const ST = { ok: 'var(--mnv-path-ok)', warn: 'var(--mnv-path-warn)', busy: 'var(--mnv-path-busy)' };
const PEOPLE = ['Priya Raman', 'Tomás Varga', 'Joon Park', 'Mira Holt', 'Kofi Mensah'];
let path = ['pemberton', 'checkout-api', 'production', 'payments-worker'];
const LABELS = ['Organisation', 'Project', 'Environment', 'Service'];

/* deterministic numbers per path, so the same crumb always shows the same service */
function hash(s) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
function rng(seed) { let x = seed || 1; return () => { x ^= x << 13; x ^= x >>> 17; x ^= x << 5; return (x >>> 0) / 4294967296; }; }

function siblings(level) {
  if (level === 0) return ORGS.map((o) => ({ id: o.id, n: o.n, sub: o.sub, tile: o }));
  if (level === 1) return PROJECTS[path[0]].map((p) => ({ id: p[0], n: p[0], sub: p[1] }));
  if (level === 2) return ENVS.map((e) => ({ id: e.id, n: e.id, sub: e.note, st: e.st, off: e.st === 'busy' }));
  return SERVICES[path[1]].map((s) => {
    const r = rng(hash(path[1] + s + path[2]));
    return { id: s, n: s, sub: 'v2.' + (30 + Math.floor(r() * 20)) + '.' + Math.floor(r() * 9) + ' · ' + (1 + Math.floor(r() * 5)) + ' pods' };
  });
}
function resolve(level, id) {
  const next = path.slice(0, level).concat(id);
  if (level < 1) next.push(PROJECTS[next[0]][0][0]);
  if (level < 2) next.push('production');
  if (level < 3) next.push(SERVICES[next[1]][0]);
  return next;
}

/* ---------- trail ---------- */
function segInner(level, id) {
  if (level === 0) { const o = ORGS.find((x) => x.id === id); return '<span class="mnv-path__tile" style="--h:' + o.h + '" aria-hidden="true">' + o.ini + '</span><span class="mnv-path__slot"><span class="mnv-path__txt">' + esc(o.n) + '</span></span>'; }
  if (level === 1) return BOX + '<span class="mnv-path__slot"><span class="mnv-path__txt">' + esc(id) + '</span></span>';
  if (level === 2) { const e = ENVS.find((x) => x.id === id); return '<span class="mnv-path__dot" style="--c:' + ST[e.st] + '" aria-hidden="true"></span><span class="mnv-path__slot"><span class="mnv-path__txt"><span class="mnv-path__long">' + esc(id) + '</span><span class="mnv-path__short">' + esc(e.short) + '</span></span></span>'; }
  return '<span class="mnv-path__slot"><span class="mnv-path__txt">' + esc(id) + '</span></span>';
}
function label(level, id) { return level === 0 ? ORGS.find((o) => o.id === id).n : id; }
function buildTrail() {
  ol.innerHTML = path.slice(0, 3).map((id, level) =>
    '<li><button type="button" class="mnv-path__seg" data-level="' + level + '" aria-haspopup="listbox" aria-expanded="false">' +
    segInner(level, id) + CARET + '</button></li>').join('');
  $('.mnv-path__tbtn').innerHTML = segInner(3, path[3]) + CARET;
  $$('.mnv-path__seg').forEach((b, level) => b.setAttribute('aria-label', LABELS[level] + ': ' + label(level, path[level]) + '. Switch ' + LABELS[level].toLowerCase()));
}
/* re-roll: crumbs from `from` onward slide their old label out and the new one in */
function reroll(from, old) {
  const segs = $$('.mnv-path__seg');
  const ghosts = [];
  segs.forEach((b, level) => {
    if (level < from || old[level] === path[level]) return;
    const slot = $('.mnv-path__slot', b);
    const prev = document.createElement('span');
    prev.className = 'mnv-path__ghost';
    prev.innerHTML = $('.mnv-path__txt', slot).innerHTML;
    prev.setAttribute('aria-hidden', 'true');
    ghosts.push([level, slot, prev]);
  });
  buildTrail();
  if (RM.matches) return;
  const fresh = $$('.mnv-path__seg');
  ghosts.forEach(([level, , prev], k) => {
    const slot = $('.mnv-path__slot', fresh[level]);
    const txt = $('.mnv-path__txt', slot);
    slot.append(prev);
    const delay = k * 70;
    prev.animate([{ transform: 'none', opacity: 1 }, { transform: 'translateY(-100%)', opacity: 0 }], { duration: 260, delay, easing: 'cubic-bezier(.5,0,.75,0)', fill: 'both' }).onfinish = () => prev.remove();
    txt.animate([{ transform: 'translateY(100%)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 420, delay: delay + 120, easing: 'cubic-bezier(.22,1,.36,1)', fill: 'backwards' });
    const marker = fresh[level].firstElementChild;
    if (marker && marker !== slot) marker.animate([{ transform: 'scale(.6)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 380, delay: delay + 80, easing: 'cubic-bezier(.34,1.5,.5,1)', fill: 'backwards' });
  });
}

/* ---------- body ---------- */
function paintBody(swap) {
  const env = ENVS.find((e) => e.id === path[2]);
  const r = rng(hash(path.join('/')));
  const base = path[2] === 'production' ? 9000 + r() * 6000 : path[2] === 'staging' ? 300 + r() * 400 : 20 + r() * 40;
  const series = Array.from({ length: 24 }, (_, i) => base * (0.62 + 0.38 * Math.sin((i - 8) / 24 * Math.PI * 2 * 0.5 + 0.4) ** 2 + r() * 0.12));
  const rpm = Math.round(series[23]);
  const errors = Math.max(0, Math.round(rpm * (env.st === 'warn' ? 0.018 + r() * 0.01 : 0.0008 + r() * 0.002)));
  const rate = rpm ? (errors / rpm) * 100 : 0;
  const p95 = Math.round((env.st === 'warn' ? 420 : 120) + r() * 140);
  const who = PEOPLE[Math.floor(r() * PEOPLE.length)];
  const hrs = 1 + Math.floor(r() * 20);
  const sha = (hash(path.join(':')) >>> 0).toString(16).padStart(8, '0').slice(0, 7);
  const ver = siblings(3).find((s) => s.id === path[3]).sub.split(' · ')[0];
  const envEl = $('.mnv-path__env');
  envEl.style.setProperty('--c', ST[env.st]);
  envEl.innerHTML = '<span class="mnv-path__dot" style="--c:' + ST[env.st] + '" aria-hidden="true"></span>' + esc(env.id);
  $('.mnv-path__deploy').innerHTML = '<code>' + ver + '</code> deployed by ' + who + ' ' + hrs + ' h ago from <code>' + sha + '</code>';
  $('[data-k="p95"]').innerHTML = p95 + '<small> ms</small>';
  $('[data-k="rpm"]').innerHTML = fmt(rpm) + '<small> /min</small>';
  const errEl = $('[data-k="err"]');
  errEl.innerHTML = rate.toFixed(2) + '<small>%</small>';
  $('[data-k="epm"]').textContent = '· ' + errors + '/min';
  errEl.classList.toggle('is-warn', rate >= 1);
  const max = Math.max(...series) * 1.08, min = Math.min(...series) * 0.9;
  const pts = series.map((v, i) => [(i / 23) * 300, 60 - ((v - min) / (max - min)) * 54]);
  const d = 'M' + pts.map((p) => p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('L');
  $('.mnv-path__line').setAttribute('d', d);
  $('.mnv-path__area').setAttribute('d', d + 'L300 64L0 64Z');
  $('.mnv-path__now').textContent = 'now ' + fmt(rpm);
  Array.from(body.children).forEach((c, i) => c.style.setProperty('--i', i));
  if (swap && !RM.matches) { body.classList.remove('is-swap'); void body.offsetWidth; body.classList.add('is-swap'); }
}

/* ---------- the switcher ---------- */
let openLevel = -1, act = 0, opts = [], typed = '', typedAt = 0;
function openAt(level) {
  const seg = $$('.mnv-path__seg')[level];
  openLevel = level;
  opts = siblings(level);
  $('.mnv-path__ph').textContent = 'Switch ' + LABELS[level].toLowerCase();
  listbox.id = UID + '-list';
  listbox.setAttribute('aria-label', LABELS[level]);
  listbox.innerHTML = opts.map((o, i) =>
    '<li class="mnv-path__opt" role="option" id="' + UID + '-o' + i + '" data-i="' + i + '" style="--i:' + i + '" aria-selected="' + (o.id === path[level]) + '"' + (o.off ? ' aria-disabled="true"' : '') + '>' +
    (o.tile ? '<span class="mnv-path__tile" style="--h:' + o.tile.h + '" aria-hidden="true">' + o.tile.ini + '</span>' : o.st ? (o.st === 'busy' ? '<span class="mnv-path__spin" aria-hidden="true"></span>' : '<span class="mnv-path__dot" style="--c:' + ST[o.st] + '" aria-hidden="true"></span>') : level === 1 ? BOX : COG) +
    '<span><b>' + esc(o.n) + '</b><small>' + esc(o.sub) + '</small></span>' + TICK + '</li>').join('');
  $$('.mnv-path__seg').forEach((b) => { b.setAttribute('aria-expanded', String(b === seg)); b.removeAttribute('aria-controls'); });
  seg.setAttribute('aria-controls', listbox.id);
  const rr = root.getBoundingClientRect(), sr = seg.getBoundingClientRect();
  pop.hidden = false;
  const w = pop.offsetWidth;
  pop.style.setProperty('--x', Math.max(8, Math.min(sr.left - rr.left, rr.width - w - 8)) + 'px');
  pop.style.setProperty('--y', sr.bottom - rr.top + 6 + 'px');
  setAct(Math.max(0, opts.findIndex((o) => o.id === path[level])));
  listbox.focus();
}
let closedAt = 0, closedLevel = -1;
function closePop(refocus) {
  if (pop.hidden) return;
  closedAt = performance.now();
  closedLevel = openLevel;
  pop.hidden = true;
  const seg = $$('.mnv-path__seg')[openLevel];
  $$('.mnv-path__seg').forEach((b) => b.setAttribute('aria-expanded', 'false'));
  if (refocus && seg) seg.focus();
  openLevel = -1;
}
function setAct(i) {
  const els = $$('[role="option"]', listbox);
  if (!els.length) return;
  act = (i + els.length) % els.length;
  els.forEach((el, k) => el.classList.toggle('is-active', k === act));
  listbox.setAttribute('aria-activedescendant', els[act].id);
  const el = els[act];
  if (el.offsetTop < listbox.scrollTop) listbox.scrollTop = el.offsetTop;
  else if (el.offsetTop + el.offsetHeight > listbox.scrollTop + listbox.clientHeight) listbox.scrollTop = el.offsetTop + el.offsetHeight - listbox.clientHeight;
}
function pick(i) {
  const o = opts[i], level = openLevel;
  if (!o) return;
  if (o.off) {
    const el = $$('[role="option"]', listbox)[i];
    el.classList.remove('is-nope'); void el.offsetWidth; el.classList.add('is-nope');
    say(o.n + ' is still building. ' + o.sub);
    return;
  }
  closePop(false);
  if (o.id === path[level]) { $$('.mnv-path__seg')[level].focus(); return; }
  const old = path.slice();
  path = resolve(level, o.id);
  reroll(level, old);
  $$('.mnv-path__seg')[level].focus();
  body.setAttribute('aria-busy', 'true');
  later(RM.matches ? 0 : 380, () => { body.setAttribute('aria-busy', 'false'); paintBody(true); });
  say('Now viewing ' + path.slice(1).join(', ') + ' in ' + label(0, path[0]));
}

root.addEventListener('click', (e) => {
  const b = e.target.closest('.mnv-path__seg');
  if (!b) return;
  const level = +b.dataset.level;
  /* the press on this crumb blurred the list and closed it already: treat the click as the toggle */
  if (closedLevel === level && performance.now() - closedAt < 300) return;
  if (openLevel === level) closePop(true); else openAt(level);
});
root.addEventListener('keydown', (e) => {
  const segs = $$('.mnv-path__seg'), k = segs.indexOf(e.target);
  if (k < 0) return;
  if (e.key === 'ArrowDown') { e.preventDefault(); openAt(k); }
  else if (e.key === 'ArrowRight' && k < 2) { e.preventDefault(); segs[k + 1].focus(); }
  else if (e.key === 'ArrowLeft' && k > 0 && k < 3) { e.preventDefault(); segs[k - 1].focus(); }
});
listbox.addEventListener('pointermove', (e) => { const o = e.target.closest('[role="option"]'); if (o && +o.dataset.i !== act) setAct(+o.dataset.i); });
listbox.addEventListener('click', (e) => { const o = e.target.closest('[role="option"]'); if (o) pick(+o.dataset.i); });
pop.addEventListener('mousedown', (e) => { e.preventDefault(); });
listbox.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown') setAct(act + 1);
  else if (e.key === 'ArrowUp') setAct(act - 1);
  else if (e.key === 'Home') setAct(0);
  else if (e.key === 'End') setAct(-1);
  else if (e.key === 'Enter' || e.key === ' ') pick(act);
  else if (e.key === 'Escape') closePop(true);
  else if (e.key === 'Tab') { closePop(false); return; }
  else if (e.key.length === 1 && /\S/.test(e.key)) {
    const now = performance.now();
    typed = now - typedAt > 600 ? e.key.toLowerCase() : typed + e.key.toLowerCase();
    typedAt = now;
    const order = opts.map((o, i) => i).slice(act + (typed.length === 1 ? 1 : 0)).concat(opts.map((o, i) => i).slice(0, act + (typed.length === 1 ? 1 : 0)));
    const hit = order.find((i) => opts[i].n.toLowerCase().startsWith(typed));
    if (hit !== undefined) setAct(hit);
  } else return;
  e.preventDefault();
});
pop.addEventListener('focusout', (e) => { if (!pop.contains(e.relatedTarget)) closePop(false); });
root.addEventListener('pointerdown', (e) => {
  if (!pop.hidden && !pop.contains(e.target) && !e.target.closest('.mnv-path__seg')) closePop(false);
});

buildTrail();
paintBody(false);
